(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-obs-diff-accurate-pruning-for-diffus-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-1\">一 · 开场：一条被 SLO 卡死的文生图队列</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-2\">二 · 旧方案：一次性剪枝在扩散模型上为何失准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-3\">三 · 为什么非改不可：显存、带宽与离线成本的错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-4\">四 · 旧方案的另一种形态：全局重要性估计的陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-5\">五 · 工程判断：剪枝在推理栈中的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-6\">六 · 在线文生图队列里，剪枝被当成“在线优化”的那一刻</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-7\">七 · 请求形态的四个可测维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-8\">八 · 批大小与 CFG 批合并如何塑造剪枝收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-9\">九 · SLO 与长尾：时延预算怎么分配到步上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-10\">十 · 校准负载与在线负载必须同分布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-11\">十一 · 方案反过来限制负载的三条路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-12\">十二 · 负载形态如何反向约束剪枝方案：校准口径、批形态与 SLO 边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-13\">十三 · 剪枝掩码落到 Tensor Core 上的真实形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-14\">十四 · 数据类型选择：FP16、BF16、FP8 与 NVFP4 的误差结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-15\">十五 · 累加精度与二阶统计的数值路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-16\">十六 · Blackwell 特性如何改变剪枝 kernel 的写法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-17\">十七 · 剪枝 kernel 与量化 kernel 的接口代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-18\">十八 · 精度预算的分配判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-19\">十九 · 算子边界：OBS 重建与 Blackwell 数值格式的接缝</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-20\">二十 · 显存账本的三个账户：权重、激活、无 KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-21\">二十一 · HBM3e 容量怎么算：可用量不是标称量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-22\">二十二 · 带宽瓶颈的位置：权重流与激活流是两条不同的路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-23\">二十三 · 分页、压缩、复用、卸载：扩散侧各自对应什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-24\">二十四 · 一个可复算的显存预算（含剪枝与量化叠加）</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-25\">二十五 · 工程判断：账本先于手段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-26\">二十六 · 剪枝模型的批形态：CFG 合并与稀疏权重的调度耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-27\">二十七 · Chunked prefill 在扩散链路里的对应物：文本编码与 VAE 解码的分段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-28\">二十八 · 优先级与抢占：SLO 分档下的批重组</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-29\">二十九 · 分离式预填/解码在扩散上的映射：编码与去噪分离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-30\">三十 · 时延与吞吐的取舍面：用剪枝收益换 SLO 余量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-31\">三十一 · 从单卡校准到多卡切分：剪枝模型的并行拓扑约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-32\">三十二 · NVLink 5 与 NVSwitch：集合通信的带宽账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-33\">三十三 · All-to-All 与 EP：扩散主干里最贵的通信形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-34\">三十四 · PP 与 DP：剪枝收益被稀释与放大的两种方式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-35\">三十五 · NIXL 传输：分离式预填/解码下的权重与激活搬运</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-36\">三十六 · 通信何时成为瓶颈：一个可计算的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-37\">三十七 · 剪枝与并行拓扑的耦合边界：通信何时反噬收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-38\">三十八 · 精度塌陷的三种形态与时间步归因</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-39\">三十九 · OOM 的两个来源：二阶统计与激活峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-40\">四十 · 批抖动与尾延迟：剪枝不改变批形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-41\">四十一 · 静默降级：没有报错的质量漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-42\">四十二 · 回滚与容量兜底的具体判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-43\">四十三 · 校准偏差与静默降级的诊断闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-44\">四十四 · 为什么这套基准必须先把口径钉死</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-45\">四十五 · 模型与硬件档位：三组变量必须固定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-46\">四十六 · batch、并发与指标定义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-47\">四十七 · 数字怎么读：三类不可比的提升</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-48\">四十八 · 一个具体例子：同一条请求在两种口径下的读数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-49\">四十九 · 工程判断：先建口径，再谈收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-50\">五十 · 剪枝收益的边界：口径、失效条件与离线代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-51\">五十一 · 迁移到非 DiT 主干：先看层结构与激活统计是否成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-52\">五十二 · 时间步覆盖：迁移到少步采样器与流匹配时的重采样策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-53\">五十三 · 与量化叠加：掩码与缩放粒度必须分开管理</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-54\">五十四 · 规模上限：二阶统计的存储与求逆决定能剪多大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-55\">五十五 · 领域迁移：哪些推理形态不适用，判断依据是什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-56\">五十六 · 工程判断：迁移前必须回答的三个问题</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:590px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">离线校准：采样一批校准提示与时间步，前向收集各层输入激活并累计二阶统计。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">逐层重建：对每个线性层按 OBS 准则选择剪枝列，并同步更新保留权重以…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">稀疏化落地：将剪枝掩码与更新后的权重写回模型，形成一次性剪枝后的扩散主…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">采样推理：剪枝模型沿用原采样器与 CFG 批合并策略，按原步数或蒸馏步…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码与服务：VAE 解码输出图像，剪枝后模型可叠加 FP8／NVFP4…</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-1\">一 · 开场：一条被 SLO 卡死的文生图队列</h3>\n<p>设想一个已上线的文生图服务：GB200 NVL72 机柜里挂着若干 B200，前端是连续批处理队列，后端是 TensorRT-LLM 或 vLLM 的扩散采样路径。SLO 写得很具体——P99 首图返回时间不超过某个阈值，队列深度超过阈值时触发限流。压测时链路各段都还算健康，唯独 DiT 主干这一步把 P99 顶了上去：每个请求要跑 N 步去噪，每步都要把整份 DiT 权重从 HBM 读一遍参与矩阵乘，CFG 又把条件与非条件分支拼成双倍批。权重显存占用与每步矩阵乘时延同时成为瓶颈，扩容只能靠加卡，而加卡又受机柜功耗与 NVLink 域边界约束。</p>\n<p>工程上第一反应是砍步数：步数蒸馏、一致性模型这类路线把 N 步压到几步，收益直接。但它们与权重压缩是两条正交的线——蒸馏后的少步模型仍然要每步读全量权重，显存占用没变，矩阵乘算力没变。第二条线是量化：FP8 乃至 NVFP4 把权重位宽压下来，带宽与显存同步下降，这条线在 Blackwell 上有 tcgen05 与 TMEM 支撑，落地路径清晰。第三条线是缓存复用，但扩散主干没有 KV cache 这种天然可复用的结构，激活缓存只在特定块间复用场景成立。第四条线就是本部分要处理的现场：剪枝，直接改变权重与激活规模。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-2\">二 · 旧方案：一次性剪枝在扩散模型上为何失准</h3>\n<p>剪枝在 LLM 上已经跑通了一套成熟范式：用少量校准样本前向一遍，收集每层输入激活，按某种重要性准则（幅度、激活感知、或 OBS 式二阶误差补偿）一次性裁掉一批权重，必要时再做轻量恢复微调。这套范式的前提是：校准分布能代表推理分布，且模型对单一输入的响应在统计上是平稳的。扩散模型恰好打破了这个前提。</p>\n<p>扩散采样是一条轨迹：从高噪的纯噪声潜变量出发，经数十步逐步去噪到低噪的干净潜变量。同一个线性层，在第 3 步（高噪段）和第 30 步（低噪段）看到的输入激活分布差异显著——高噪段激活更接近各向同性、低噪段激活带有明显的结构性与稀疏性。传统一次性剪枝准则若只用单步、单样本的权重重要性估计，等价于在轨迹的一个点上做局部线性化，然后把结论外推到整条轨迹。结果就是：剪枝掩码在采样早期看起来无害，到了后期误差被逐层放大，生成图像出现结构性崩坏——不是轻微的画质下降，而是构图错位、纹理重复、语义漂移。</p>\n<p>把这件事写成代价函数更清楚。设某层权重为 <span>W</span>，输入激活为 <span>X</span>，剪枝后的权重为 <span>Ŵ</span>，传统单步准则优化的目标是：</p>\n<div class=\"formula\">$$\\min_{\\hat{W}} \\| W X_t - \\hat{W} X_t \\|_2^2 \\quad \\text{s.t.} \\quad \\hat{W} \\text{ 在掩码 } M \\text{ 下稀疏}$$</div>\n<p>问题在于 <span>X_t</span> 只取了某一个时间步 <span>t</span> 的激活。真实采样轨迹上的层输出误差是沿轨迹累积的，单点最小化不能保证轨迹上的误差有界。这就是“时间步敏感”在剪枝语境下的具体含义：不是模型对时间步本身敏感，而是剪枝准则的统计基础只覆盖了轨迹的一个切片。</p>\n<p>系统代价上，这种失准不是免费的。质量退化迫使部署侧保留更高的稀疏度上限——本来想裁到某个比例，实测发现必须回退，权重显存与矩阵乘算力的节省随之缩水。更糟的是，失准的剪枝结果与量化叠加时误差会被放大：剪枝掩码决定了哪些权重被置零，量化缩放决定了剩余权重的表示精度，两者若各自独立校准，剪枝误差与量化误差在同一层输出上叠加，且没有机制保证叠加后仍在可接受范围内。工程上只能靠反复试：换校准集、换时间步、换稀疏度，每一轮都要跑完整采样评估，迭代成本高，且没有收敛保证。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-3\">三 · 为什么非改不可：显存、带宽与离线成本的错配</h3>\n<p>把旧方案的痛点拆到硬件账本上，会看到三笔账同时不划算。第一笔是权重显存：DiT 主干的参数量在 B200 的 192GB HBM 档位上不是小数目，叠加 CFG 批合并后的激活峰值，单卡可容纳的并发批被压得很低。剪枝本该是缓解这一项的直接手段，但失准迫使稀疏度回退，收益打折。第二笔是每步带宽：每步去噪都要把权重从 HBM 搬到 SM，权重位宽与稀疏度共同决定这一步的搬运量；剪枝若不能裁到位，带宽节省有限，P99 首图时间就下不来。第三笔是离线成本：一次性剪枝的卖点正是“一次校准、无需迭代重训”，但失准导致的反复试错把这个卖点抵消了——名义上一次性，实际变成多轮人工调参。</p>\n<p>还有一个容易被误判的成本项：二阶统计矩阵的存储与求逆。OBS 式方法要对每层输入激活累计二阶统计（Hessian 近似），层宽越大，这个矩阵越大，求逆的算力开销越高。这笔开销发生在离线校准阶段，不进入在线请求队列，但它决定了校准能否在单卡或少量卡上完成、能否在可接受的时间内跑完。若把剪枝误当成在线优化，就会在容量规划时把离线开销错算进在线 SLO，得出错误的扩缩容结论。正确的账本是：在线只受益于权重变小后的每步时延下降与显存占用下降，离线成本单独核算。</p>\n<p>具体到一个请求的链路：服务端加载剪枝后的 DiT 主干，文本编码器输出提示嵌入，采样器在若干时间步上迭代去噪，每步执行注意力与前馈计算，CFG 把条件与非条件分支拼成一个批提高利用率，最终潜变量送入 VAE 解码返回队列。这条链路里，剪枝能动的只有线性层与卷积层的权重规模；采样器步数、CFG 批形态、VAE 解码路径都不变。也就是说，剪枝的收益边界很清晰——它降低权重显存与矩阵乘算力，但不改变采样轨迹的长度，也不改变 CFG 的批结构。任何期待剪枝单独把 P99 拉到达标的判断都是错的，它必须与步数蒸馏、量化、批调度叠加才构成完整答案。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-4\">四 · 旧方案的另一种形态：全局重要性估计的陷阱</h3>\n<p>除了单步校准，旧方案还有一类变体：用全局重要性分数（比如跨层归一化的权重幅度）一次性决定所有层的剪枝比例。这种做法在 LLM 上有时能跑通，因为 LLM 的激活分布相对平稳；在扩散模型上它的问题更隐蔽——不同时间步上，不同层的敏感度排序会翻转。高噪段某些层承担主要的噪声建模，低噪段另一些层承担结构细化，全局分数把这两类贡献混在一起平均，得到的掩码在轨迹两端都不最优。</p>\n<p>这类失准的代价体现在评估环节：部署侧要判断剪枝是否可接受，只能跑完整采样看生成质量。扩散模型的生成质量评估本身开销不小——要跑完整条轨迹、要过 VAE 解码、要做人工或自动指标评估。每一轮剪枝参数调整都伴随一轮完整评估，迭代周期以小时计。这就是为什么“一次性”这个属性在扩散剪枝上格外值钱：它不是省了几次微调，而是省掉了多轮完整采样评估的工程循环。</p>\n<p>把旧方案的问题收敛成一句话：剪枝准则的统计基础必须覆盖采样轨迹，而旧方案只覆盖了轨迹上的一个点或一个全局平均。这个判断直接指向 OBS-Diff 的切入点——用多时间步、多样本的激活统计替代单步重要性估计，把误差补偿做到层输出上。后续部分会展开这个机制的具体构造，本部分只负责把“为什么旧方案在扩散模型上失准、失准的系统代价是什么”钉死。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-5\">五 · 工程判断：剪枝在推理栈中的位置</h3>\n<p>对容量规划者而言，本部分给出的判断是：剪枝是离线压缩步骤，不是在线优化手段。它的成本结构是“离线一次性校准 + 在线持续收益”，收益项是权重显存与每步矩阵乘时延，成本项是校准阶段的激活收集与二阶统计求逆。在 B200/GB200 这类档位上，权重显存与 HBM 带宽是硬约束，剪枝与 FP8/NVFP4 量化叠加是自然的组合——量化压位宽，剪枝压非零元素数量，两者作用在不同维度上。但叠加时必须分别管理剪枝掩码与量化缩放，不能共用一套缩放粒度，否则剪枝误差与量化误差会在层输出上耦合放大，且没有解析手段分离两者贡献。</p>\n<p>另一个判断是关于失败模式的监控：剪枝后必须监控生成质量漂移，且监控要覆盖采样轨迹的两端——高噪段与低噪段分别抽样评估，而不是只看最终图像。时间步覆盖不足是这类方法的主要失败模式，而它恰恰在最终图像上表现为“某些请求正常、某些请求崩坏”的间歇性症状，容易被误判为批调度或队列问题。把时间步覆盖作为校准阶段的显式检查项，比事后在生成质量上排查更省工程成本。</p>\n<p>最后落在具体机制上：旧方案失准的根源是剪枝准则的统计基础与采样轨迹不匹配，OBS-Diff 的应对是把校准扩展到多时间步、把误差补偿做到层输出最小化。这个应对是否成立，取决于二阶统计能否在有限校准成本下代表整条轨迹，以及求逆开销能否被离线预算吸收。这两点在材料中均未给出定量结果，部署侧只能在具体硬件档位与 SLO 下实测稀疏度上限与质量漂移曲线，再决定是否把剪枝纳入服务化前置压缩步骤。</p>\n\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-6\">六 · 在线文生图队列里，剪枝被当成“在线优化”的那一刻</h3>\n<p>一个典型的在线文生图服务在高峰期的形态是这样的：请求队列里堆着长短不一的提示，调度器按显存档位把批拼到上限，采样器在每个时间步上调用一次 DiT 主干，CFG 再把条件与非条件分支合并进同一个批以提高利用率。此时运维看到的是每步矩阵乘的时延与权重常驻显存，而不是“稀疏度”这个抽象指标。问题在于，一旦有人把剪枝当作在线侧的优化手段接进这条链路，成本判断就会失真：OBS-Diff 的校准与二阶统计求逆是离线一次性开销，在线侧唯一能拿到的收益是权重变小后每步矩阵乘变短、权重常驻显存下降。把校准塞进请求路径，等于用离线成本去换在线 SLO，方向从一开始就错了。</p>\n<p>旧方案在这个场景下的失效条件很具体。传统一次性剪枝准则通常只取单步或单样本的权重重要性，而扩散模型的激活分布在整条采样轨迹上差异显著：高噪段与低噪段的输入统计不是同一个分布。用单步统计去近似整条轨迹，剪枝误差在未被覆盖的时间步上被系统性低估，表现为某些请求在高噪段结构崩坏、某些在低噪段纹理劣化。逐层重建的目标可写成</p>\n<div class=\"formula\">$$\\min_{\\hat{W}} \\| W X - \\hat{W} X \\|_2^2 \\quad \\text{s.t.} \\quad \\hat{W} \\text{ 在掩码 } M \\text{ 下稀疏，逐列补偿：} \\delta_q = -\\frac{w_q}{[H^{-1}]_{qq}}\\, H^{-1}_{:,q}$$</div>\n<p>其中 $H$ 由校准激活累计而来。可见误差是否被正确补偿，完全取决于 $X$ 是否覆盖了真实采样轨迹；覆盖不足时，$H^{-1}$ 给出的补偿方向本身就是偏的。</p>\n<p>系统代价要分两栏记。离线栏：二阶统计矩阵的存储与求逆随层宽增长，层越宽显存与算力开销越高，这是校准任务的成本，不进入在线队列。在线栏：剪枝降低的是 DiT 线性层权重显存与矩阵乘算力；扩散主干没有 KV cache，显存节省只来自权重与激活，不能套用自回归模型的缓存账本。与 FP8／NVFP4 叠加时，剪枝掩码与量化缩放需分别管理，共用缩放粒度会放大剪枝误差，必须分开验证。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>成本归属</th><th>失效条件</th></tr></thead><tbody><tr><td>多时间步校准与前向统计</td><td>离线一次性</td><td>时间步覆盖不足，统计不代表整条轨迹</td></tr><tr><td>二阶矩阵存储与求逆</td><td>离线，随层宽增长</td><td>超大 DiT 上层宽导致显存吃紧</td></tr><tr><td>稀疏权重矩阵乘</td><td>在线每步时延</td><td>与量化缩放共用粒度时精度损失叠加</td></tr><tr><td>CFG 批合并</td><td>在线批形态不变</td><td>剪枝不改变批形态，收益只来自权重变小</td></tr></tbody></table>\n<p>工程判断因此落在校准负载的设计上：校准提示的长度分布要贴近线上请求，时间步要在轨迹上覆盖高噪与低噪区间，否则一次性剪枝的稀疏度上限会被质量退化提前封死。论文未给出稀疏度、FID 与吞吐的定量结果，部署收益必须在具体硬件档位与 SLO 下实测；能确定的边界是，它是服务化前置的离线压缩步骤，不与在线批调度争资源。</p>\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-7\">七 · 请求形态的四个可测维度</h3>\n<p>把扩散推理的负载拆成可核查的量，先要拒绝“平均一张图”这种口径。文生图服务的请求至少要在四个维度上分别采样：提示词 token 长度分布（文本编码器侧，决定 cross-attention 的键值规模与首段时延）、目标分辨率与宽高比（决定潜变量网格尺寸，进而决定每步注意力的序列长度）、采样步数与采样器类型（决定 DiT 被调用的次数）、以及 CFG 是否开启及引导强度。这四个维度不是独立的：分辨率翻倍使注意力序列长度按面积增长，而步数只做线性叠加，因此高分辨率短步数与低分辨率长步数在总算力上可能接近，但在时延结构上完全不同——前者每步更重、步间间隔更长，后者步数密集、调度开销占比更高。</p>\n<p>测量口径要落到可复现的统计量上：对提示长度记录分位数（p50/p90/p99）而非均值；对分辨率记录联合分布而非边缘分布；对步数记录实际生效值（含蒸馏模型的固定少步）。并发侧要区分“到达并发”与“在飞并发”：前者是单位时间进入队列的请求数，后者是任一时刻真正占用显存的请求数，二者之间隔着排队与批聚合。SLO 则要按分位数定义，例如 p90 端到端时延上限与 p99 首图返回上限，而不是平均值承诺。长尾的来源在扩散服务里非常具体：超长提示、超高分辨率、需要多图返回的请求，以及因批内其他请求分辨率不一致而被迫拆批的调度抖动。</p>\n<div class=\"formula\">$$\\text{每请求总算力} \\approx S \\cdot \\big( A(L_{\\text{lat}}, d) + B(L_{\\text{text}}) \\big) \\cdot (1 + \\mathbb{1}_{\\text{CFG}})$$</div>\n<p>其中 S 为步数，A 为潜变量自注意力的规模项（随潜变量 token 数 L_lat 与通道维 d 增长），B 为 cross-attention 随文本长度增长的项。这个式子给出一个工程判断：CFG 开启直接把每步的批内行数翻倍，是负载形态里最容易被低估的乘性因子；而 L_lat 的增长是超线性的，长尾请求的代价主要来自分辨率而非提示长度。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-8\">八 · 批大小与 CFG 批合并如何塑造剪枝收益</h3>\n<p>扩散主干的批形态与自回归解码不同：没有 KV cache 的逐 token 增长，批是一次性拼好、整批走完所有步。CFG 的实现方式决定了这个批的形状——把条件分支与非条件分支在批维上拼接，等效批大小为请求数乘二。这意味着显存占用中激活部分随批线性上升，而权重部分是常量。剪枝恰好压缩的是常量项：权重显存与每步矩阵乘的算力。因此在低并发、小批的场景下，剪枝的显存收益占比高（权重是主要占用）；在高并发、大批的场景下，激活与中间张量占据主导，剪枝的显存收益被稀释，但每步矩阵乘时延的下降仍然对吞吐有贡献。</p>\n<p>这里存在一个方案反过来限制负载的机制：剪枝后的层若以稀疏掩码参与矩阵乘，实际加速取决于硬件与内核是否真正利用稀疏性。若稀疏结构不被张量核心直接支持，权重虽小、算力却未必省，服务端就只能靠“更小的权重装得下更大批”这一条路径获益，即用显存节省换批大小提升。此时容量规划的自由度变成：在固定显存档位下，剪枝把权重腾出的空间折算成可并发的请求数上限。这个折算必须实测，因为激活占用随分辨率变化，不能用一个固定倍数外推。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>主导显存项</th><th>剪枝主要贡献</th><th>需实测的口径</th></tr></thead><tbody><tr><td>低并发、高分辨率、长步数</td><td>激活与中间张量</td><td>每步矩阵乘时延</td><td>单请求 p90 时延、步间间隔</td></tr><tr><td>高并发、小分辨率、少步蒸馏</td><td>权重（常量）</td><td>权重显存换批上限</td><td>最大在飞批、显存水位</td></tr><tr><td>CFG 开启、批合并</td><td>激活（行数翻倍）</td><td>每步算力按行摊薄</td><td>批内行数、每行时延</td></tr></tbody></table>\n<p>具体例子：一个服务在固定显存档位下，CFG 批合并把 8 个请求拼成 16 行，若权重占据显存的主要部分，剪枝后权重下降使得同一档位能容纳 12 个请求即 24 行；但若这批请求都是高分辨率，激活项先把显存吃满，批上限的提升就远小于按权重比例估算的值。这就是“方案限制负载”的具体形态：剪枝给出的容量增量必须按分辨率分层核算，而不是全局一个系数。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-9\">九 · SLO 与长尾：时延预算怎么分配到步上</h3>\n<p>扩散请求的端到端时延可分解为排队、文本编码、S 步去噪、VAE 解码与后处理。SLO 若按端到端分位数定义，则预算分配必须显式：去噪段通常占主导，其内部又可分成每步的矩阵乘时延与步间调度开销。剪枝影响的是每步矩阵乘项，对调度开销无影响；步数蒸馏影响的是 S 这个乘数。二者叠加时，收益不是简单相加——步数减少会让调度开销在总时延中的占比上升，剪枝带来的每步时延下降被相对稀释。容量规划时应把“每步时延 × 步数”与“固定开销”分开建模，否则会把剪枝收益高估。</p>\n<p>长尾在扩散服务里有一个特殊来源：批内异构。连续批处理在自回归解码里靠逐 token 调度实现细粒度拼批，而扩散的整批同步推进使得批内必须等到最慢的成员完成所有步。若一个批里混入了高分辨率请求，整批的每步时延被拉长，低分辨率请求被迫陪跑。缓解手段是按分辨率与步数分桶，桶内拼批；代价是桶间负载不均时出现空闲，降低整体利用率。这是一个典型的“负载塑造方案”的回路：SLO 的分位数要求迫使服务端放弃全局拼批，转而接受分桶带来的利用率损失。</p>\n<div class=\"formula\">$$\\text{p90 端到端} \\approx W_q^{(90)} + T_{\\text{text}} + S \\cdot \\big( t_{\\text{step}} + t_{\\text{sched}} \\big) + T_{\\text{VAE}}$$</div>\n<p>可核查的测量口径是：分别记录 W_q、T_text、每步 t_step 的分布（而非总和）、t_sched、T_VAE，并按请求的分辨率与步数分层统计。只有分层后的分位数才能回答“剪枝把 p90 拉低了多少”这个问题，因为剪枝只作用于 t_step 项。若不分层，长尾请求会把 t_step 的分布拉宽，掩盖剪枝在中位请求上的实际效果。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-10\">十 · 校准负载与在线负载必须同分布</h3>\n<p>OBS-Diff 的校准阶段在多个时间步上前向收集输入激活、累计二阶统计。这里的负载形态问题不是在线服务的并发，而是校准集与线上请求的分布匹配。校准提示的长度分布若显著短于线上 p90，则 cross-attention 层的激活统计偏窄，剪枝在这些层上的误差补偿就建立在不具代表性的二阶矩阵上；同理，校准用的分辨率若单一，潜变量 token 数固定，自注意力层的统计也只覆盖一个序列长度。方法本身对时间步覆盖敏感（这是它的主要失败模式），但对输入形态的覆盖同样构成隐性约束。</p>\n<p>工程上可执行的约束是：校准批的提示长度按线上分位数分层抽样，分辨率覆盖主要桶，时间步在轨迹上均匀或按敏感度采样并记录覆盖区间。校准是离线一次性任务，其成本属于离线开销——二阶统计矩阵的存储与求逆随层宽增长，层越宽显存与算力开销越高。这与在线推理成本是两笔账，不能混算。一个具体例子：若线上 p99 提示长度是 p50 的数倍，而校准只用了短提示，剪枝后在高噪段的 cross-attention 输出误差可能被低估，表现为长提示请求的质量退化先于短提示暴露。测量口径上，应把校准集的长度与分辨率分布连同剪枝掩码一起版本化，作为可追溯的部署产物。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-11\">十一 · 方案反过来限制负载的三条路径</h3>\n<p>第一条是稀疏结构对批形态的约束。若剪枝产生的稀疏模式是逐列不规则掩码，内核可能退回稠密计算或引入额外的索引开销，此时每步时延不降反升，服务端只能靠减小批来维持 SLO，等于方案压缩了可用并发。第二条是量化叠加的耦合：剪枝掩码与 FP8／NVFP4 的缩放粒度需分别管理，若共用缩放粒度，剪枝误差与量化误差在同一组权重上叠加，精度损失不可分解，验证时必须做剪枝×量化的二维矩阵而非单轴扫描。第三条是显存碎片：剪枝后权重变小，但若分配器按原尺寸预留或稀疏存储引入额外元数据，实际显存水位未必线性下降，批上限的提升需要按实测水位而非按权重字节数估算。</p>\n<p>这三条路径共同指向一个工程判断：剪枝的部署收益必须在目标硬件档位与目标 SLO 下用分层口径实测，包括每步时延的分辨率分层分布、最大在飞批与显存水位、以及剪枝×量化的精度矩阵。论文材料未给出稀疏度、FID、吞吐等定量结果，因此任何容量外推都必须以本地实测为准，不能引用未核验的数字。校准成本与稀疏度上限是这条路径的两个边界条件：校准覆盖不足会限制可用稀疏度，而二阶统计的离线开销会限制校准集规模，二者共同决定剪枝在服务化前置步骤中的实际位置。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-12\">十二 · 负载形态如何反向约束剪枝方案：校准口径、批形态与 SLO 边界</h3>\n\n<p>OBS-Diff 的校准负载必须与线上请求的输入长度分布对齐，否则二阶统计会系统性偏离。文生图请求的提示长度呈长尾分布，短提示（数个 token）与长提示（数百 token）在文本编码器输出嵌入上的激活幅值差异显著，而剪枝层看到的是这些嵌入经注意力与前馈后的输入激活。校准集若只取均值附近的提示长度，长尾请求在剪枝后会出现更大的层输出误差——因为 OBS 的逐列补偿量 <span class=\"formula\">$$\\delta_q = -\\frac{w_q}{[H^{-1}]_{qq}}\\, H^{-1}_{:,q}$$</span> 依赖 <span class=\"formula\">$$H = \\mathbb{E}[XX^\\top]$$</span> 的逆，而 <span class=\"formula\">$$H$$</span> 由校准激活的协方差决定；长尾提示贡献的激活方向若在校准集中缺席，<span class=\"formula\">$$H^{-1}$$</span> 在这些方向上的曲率被低估，补偿量随之失准。可核查的测量口径是：记录校准集提示长度分布的分位数（P50/P90/P99）与线上队列的实际分布逐桶对比，并统计每个长度桶内被剪列的数量占比；若 P99 桶的剪列占比显著低于 P50 桶，说明长尾方向未被充分覆盖。</p>\n\n<p>并发与批大小通过 CFG 批合并直接塑造剪枝方案的在线代价。CFG 把条件与非条件分支拼成一个批，批大小翻倍，剪枝不改变这一批形态，但剪枝后的稀疏权重矩阵乘在批维度上的利用率取决于批大小：批太小则矩阵乘退化为访存受限，剪枝带来的算力节省无法兑现，显存节省却已发生；批太大则激活显存成为瓶颈，而扩散主干无 KV cache，显存节省只能来自权重与激活。可核查口径为：在固定 SLO 下扫描批大小，记录每步 DiT 前向的时延与峰值显存，找出时延随批大小近似线性的区间——该区间上界即剪枝收益能被算力节省兑现的批大小上限。超出该上限后，剪枝只降低权重显存，不再降低每步时延，SLO 的改善来自显存腾挪而非算力。</p>\n\n<p>校准成本是离线开销，但它反向限制了可接受的稀疏度上限。二阶统计矩阵的存储与求逆随层宽平方增长，层宽越大，<span class=\"formula\">$$H^{-1}$$</span> 的显存与求逆算力越高；对超大 DiT，逐层串行校准的墙钟时间可能超过在线服务的部署窗口。工程判断是：把校准时间步覆盖与稀疏度做联合预算——时间步覆盖越广，<span class=\"formula\">$$H$$</span> 越能代表整条采样轨迹，但校准前向次数线性增加；稀疏度越高，逐列补偿的累积误差越大，需要更密的覆盖来压制。可核查口径为：固定校准样本数与时间步数，记录每层 <span class=\"formula\">$$H^{-1}$$</span> 的求逆耗时与峰值显存，并与该层剪枝后在线每步时延的下降做对比；若某层的离线求逆成本远高于其在线时延收益，该层应跳过剪枝或降低稀疏度。与 FP8／NVFP4 叠加时，剪枝掩码与量化缩放需分别管理，共用缩放粒度会放大剪枝误差，必须分开验证精度损失。</p>\n\n<table class=\"mini\"><thead><tr><th>负载维度</th><th>对剪枝方案的约束</th><th>可核查口径</th></tr></thead><tbody><tr><td>提示长度长尾</td><td>校准集须覆盖 P99 长度桶，否则 <span class=\"formula\">$$H^{-1}$$</span> 曲率低估</td><td>长度桶剪列占比对比</td></tr><tr><td>批大小</td><td>存在时延线性区间上界，超出后剪枝只省显存</td><td>每步时延与峰值显存扫描</td></tr><tr><td>稀疏度</td><td>受离线求逆成本与补偿误差累积双重限制</td><td>逐层求逆耗时 vs 在线时延收益</td></tr></tbody></table>\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-13\">十三 · 剪枝掩码落到 Tensor Core 上的真实形态</h3>\n<p>OBS-Diff 的产物是一组带掩码的线性层权重：某些列被整列置零，其余列被 OBS 补偿项改写。这个形态在 Blackwell 上并不天然高效。第五代 Tensor Core 的稠密 MMA 指令按固定 tile 形状吃满操作数，稀疏性只有走结构化通道（如 2:4 或更大的块稀疏）才能被硬件直接跳过；OBS 逐列剪枝产生的是非结构化掩码，硬件仍会为被剪列付出乘加周期，只是乘数为零。因此部署侧的第一层判断是：剪枝带来的收益先体现在权重显存与加载带宽上，其次才是算力。若要把算力收益拿回来，需要把列掩码重排成 tile 对齐的块稀疏，或在加载时把稀疏权重压成紧凑布局、由 kernel 用 gather 方式重建操作数——后者在 tcgen05 路径上会打断 Tensor Core 的连续流水，代价是每步矩阵乘的启动开销上升。</p>\n<p>以 DiT 的一个前馈层为例，权重形状为 $d \\times 4d$，OBS 按输入通道列剪枝，剪掉比例 $s$ 后权重非零元素数为 $(1-s)\\cdot 4d^2$。在 FP16 下该层权重占 $8d^2$ 字节，剪枝后按稠密存储仍是同样字节数（零值照样占位），只有改用压缩存储才降到 $(1-s)\\cdot 8d^2$ 加上索引开销。这就是为什么剪枝必须与量化、稀疏布局一起设计：单独剪枝在稠密 kernel 上只省了 DRAM 读取的有效带宽，没省 Tensor Core 周期。</p>\n<p>具体例子：一个 $d=3072$ 的 DiT 块，FFN 权重约 37.7 MB（FP16 稠密），按 50% 列剪枝后若仍稠密存储，显存不变；若压成块稀疏并按 FP8 存储，权重降到约 9.4 MB 量级，每步该层的权重读取时间随之下降，而 MMA 周期是否下降取决于稀疏 tile 是否被 tcgen05 识别。工程判断很直接：先确认目标 kernel 支持哪种稀疏粒度，再决定 OBS 的剪枝单元是单列还是列块。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-14\">十四 · 数据类型选择：FP16、BF16、FP8 与 NVFP4 的误差结构</h3>\n<p>OBS 补偿项 $\\delta_q = -\\frac{w_q}{[H^{-1}]_{qq}} H^{-1}_{:,q}$ 的数值质量直接决定剪枝后层输出误差。补偿项是若干列的线性组合，动态范围可能远大于原权重，若用低精度存储补偿后的权重，量化误差会与剪枝误差叠加。BF16 的 8 位指数保证补偿项不溢出，但 7 位尾数在 $H^{-1}$ 病态时引入的相对误差可达千分之几量级；FP16 尾数更多但指数窄，遇到大补偿项有溢出风险。因此校准阶段求逆与补偿计算应在 FP32 累加下完成，写回时再降到部署精度。</p>\n<p>FP8（E4M3）按块缩放时，每 16 或 32 个元素共享一个缩放因子，块内动态范围被压缩，补偿项中幅度小的列容易被量化成零，等效于在 OBS 掩码之外又引入一层非结构化稀疏——这部分稀疏不受 OBS 误差控制，属于纯量化噪声。NVFP4 的 4 位尾数加两级缩放（每 16 元素一个 FP8 缩放、每张量一个 FP32 缩放）把粒度做得更细，但 4 位有效精度意味着权重相对误差在百分之几量级，对已经剪枝的层，剩余权重承担了全部输出，误差不再有冗余列分摊。</p>\n<div class=\"formula\">$$\\|\\Delta y\\|_2 \\approx \\|W X - \\hat{W}X\\|_2 + \\|\\hat{W}X - Q(\\hat{W})X\\|_2,\\quad \\text{第二项} \\sim \\epsilon_q \\|\\hat{W}\\|_F \\|X\\|_2$$</div>\n<p>公式逐项：第一项是 OBS 剪枝误差，由 $H^{-1}$ 与剪枝列的选择决定，校准时间步覆盖不足时这一项被低估；第二项是量化误差，$\\epsilon_q$ 为数据格式的相对精度（FP8 约 $2^{-3}$ 量级有效位、NVFP4 约 $2^{-2}$ 量级），$\\|\\hat{W}\\|_F$ 是剪枝后权重范数，$\\|X\\|_2$ 是激活范数。两项相加说明剪枝与量化不是独立可加的：剪枝抬高了剩余权重的负载，使同样的 $\\epsilon_q$ 产生更大绝对误差。代价体现在每步矩阵乘的精度预算上——若叠加 NVFP4，需要给 OBS 留更保守的稀疏度，否则误差预算被量化吃光。</p>\n<p>具体例子：同一 FFN 层，FP8 块缩放（块 32）下权重误差约千分位，NVFP4 下约百分位；若该层已被剪掉一半列，NVFP4 的百分位误差直接作用在承担全部输出的剩余一半权重上，层输出相对误差相应放大。部署侧应把剪枝率与量化格式成对调参，而不是先定剪枝率再套格式。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-15\">十五 · 累加精度与二阶统计的数值路径</h3>\n<p>校准阶段的核心运算是 $H = \\sum_t X_t X_t^\\top$ 的累计与求逆。Blackwell 的 Tensor Core 在 FP16/BF16 输入下以 FP32 累加，FP8 输入同样以 FP32 累加，这使 $X X^\\top$ 的累加可以在 MMA 流水里完成而不必回读。但 $H$ 的维度是层输入宽度 $d$，对 $d=3072$ 的层，$H$ 是 $3072^2$ 的 FP32 矩阵，约 37.7 MB；对 $d$ 更大的注意力投影层，单层 $H$ 就占数十 MB，逐层串行校准时这是峰值显存的主要来源。求逆用 Cholesky 分解，复杂度 $O(d^3)$，在单卡上对每层做一次是可接受的离线开销，但层数多时累计时间不可忽略。</p>\n<p>数值上，$H$ 的条件数随校准时间步与样本的多样性上升。扩散轨迹上高噪段激活范数大、低噪段激活范数小，混合累计会让 $H$ 呈现宽动态范围，直接求逆在 FP32 下也可能放大误差。工程做法是对 $H$ 做对角加载（加 $\\lambda I$）或用分块求逆，代价是补偿项不再严格最优，剪枝误差略升。这一步的精度选择影响的是离线校准成本与剪枝后质量，不影响在线推理时延。</p>\n<p>具体例子：一个含 24 个 DiT 块的模型，每块两个线性层需校准，若每层 $H$ 平均 20 MB、求逆在 FP32 下进行，校准峰值显存由单层 $H$ 加激活决定，而非模型权重；这意味着校准可以在比推理更小的显存档位上完成，但单层宽度上限受显存约束。若某层 $d$ 超出可用显存，需按列分块累计 $H$ 的分块，再拼接求逆，代价是分块边界处的补偿精度下降。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-16\">十六 · Blackwell 特性如何改变剪枝 kernel 的写法</h3>\n<p>tcgen05 把 MMA 的累加器放到 Tensor Memory（TMEM）而非寄存器堆，释放了寄存器压力，使大 tile 的矩阵乘可以更深地流水。对剪枝后的稀疏权重，kernel 需要在发起 MMA 前把压缩权重展开成 tile 操作数；TMEM 路径上这一步若放在共享内存侧做，会与 MMA 的异步流水重叠，代价是共享内存带宽占用上升。2-SM MMA 让两个 SM 协作完成一个更大的 MMA tile，对宽输出层有利，但对稀疏掩码的 tile 对齐要求更严：一个 2-SM tile 内若只有部分列被剪，硬件仍按稠密执行，稀疏收益被摊薄。</p>\n<p>第五代 Tensor Core 对 FP8 与 NVFP4 的原生支持改变了量化落点：权重可以在加载时以 NVFP4 存储、在 MMA 前反量化到 FP8 或 BF16 参与计算，反量化发生在片上而非 DRAM，省的是权重带宽而非算力。对 OBS 剪枝模型，这意味着权重显存收益可以叠加：剪枝压缩非零元素数，NVFP4 压缩每元素位宽，两者相乘得到权重占用。但反量化路径的缩放因子管理要与剪枝掩码分开——掩码决定哪些列参与，缩放决定剩余列怎么表示，共用一套元数据会在列边界处产生错误。</p>\n<p>具体例子：GB200 NVL72 单卡 HBM 容量大，权重带宽是每步时延的主要项之一；一个剪枝 50% 并 NVFP4 量化的 DiT，权重占用降到稠密 FP16 的约八分之一量级，每步权重读取时间相应下降，而 MMA 周期是否下降取决于稀疏 tile 是否被硬件跳过。功耗侧，权重带宽下降直接减少 HBM 访问能量，这是剪枝加量化在能效上的主要贡献，算力侧的节省则取决于稀疏结构化程度。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-17\">十七 · 剪枝 kernel 与量化 kernel 的接口代价</h3>\n<p>OBS 剪枝发生在离线，产物是掩码加补偿后权重。上线时服务框架需要把这份产物转成目标 kernel 的操作数布局：稠密 kernel 要求权重按 tile 连续排布，稀疏 kernel 要求非零元素与索引分离。转换本身是一次性开销，但转换后的布局决定了每步矩阵乘能否走快路径。若掩码是非结构化的，稠密 kernel 只能把零值当普通权重算，此时剪枝的唯一在线收益是权重变小带来的带宽节省；若重排成块稀疏，kernel 可以用索引跳过整块，算力收益才出现，代价是索引读取与 tile 边界处理增加指令开销。</p>\n<p>与 FP8/NVFP4 叠加时，缩放因子的粒度必须与稀疏块对齐。块稀疏的块大小若为 32 列，FP8 块缩放也取 32 元素一块，两者边界重合，元数据可以合并管理；若块大小不一致，每个 MMA tile 需要同时查稀疏索引与缩放表，片上元数据带宽成为新瓶颈。这是剪枝与量化联合部署时最容易被忽略的接口代价。</p>\n<p>具体例子：一个按 32 列块剪枝、按 32 元素块缩放的 FFN 层，每个 MMA tile 的元数据是块索引加缩放因子，两者可打包成一条记录；若剪枝按单列、缩放按 16 元素，元数据条数翻倍且边界不对齐，kernel 在 tile 准备阶段多出一次索引重排。部署侧应在 OBS 校准前就定下块大小，让剪枝单元与量化单元同粒度。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-18\">十八 · 精度预算的分配判断</h3>\n<p>把剪枝误差与量化误差放在同一预算下看，部署侧要回答的是：给定目标层输出误差上限，稀疏度与数据格式如何分配。OBS 的补偿使剪枝误差在层输出上最小化，但补偿项本身在低精度写回时被量化；量化误差则随剩余权重范数缩放。两者的相对大小取决于 $H^{-1}$ 的条件数与校准覆盖度：时间步覆盖充分时剪枝误差小，预算可以更多给量化（更低位宽）；覆盖不足时剪枝误差主导，再低位宽只会放大总误差。</p>\n<div class=\"formula\">$$\\text{总误差预算} \\;\\approx\\; \\underbrace{\\frac{\\|w_q\\|^2}{[H^{-1}]_{qq}}}_{\\text{OBS 残差}} \\;+\\; \\underbrace{\\epsilon_q^2 \\|\\hat{W}\\|_F^2}_{\\text{量化}} \\;\\le\\; \\tau$$</div>\n<p>公式逐项：第一项是单列剪枝的残差能量，$w_q$ 是被剪列权重，$[H^{-1}]_{qq}$ 是该列在逆 Hessian 对角上的值，对角值越大说明该列对输出影响越小、剪枝越安全；第二项是量化误差能量，$\\epsilon_q$ 由格式决定。$\\tau$ 是层输出允许的误差上限。这个式子给出的是分配原则而非精确预测：它说明为什么在 $H^{-1}$ 病态（对角值小）的层上不能激进剪枝，也说明为什么 NVFP4 下要给剪枝留更保守的稀疏度。</p>\n<p>工程判断落在校准与部署的耦合上：校准阶段用 FP32 求逆得到掩码与补偿，写回时按目标格式量化，量化后的实际层误差需要在少量校准样本上回放验证，而不是只信公式。对超大 DiT，逐层验证的回放成本远低于全模型评测，是可操作的验收手段。最终落在具体机制上：OBS 的掩码单元、$H$ 的求逆精度、写回的数据格式与缩放粒度四者必须同粒度设计，任何一处错位都会让剪枝的显存收益被 kernel 的元数据开销或量化噪声抵消。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-19\">十九 · 算子边界：OBS 重建与 Blackwell 数值格式的接缝</h3>\n<p>OBS-Diff 的逐列补偿式剪枝在数学上只保证层输出的 L2 误差最小，它并不保证剪枝后的权重分布仍落在 FP8／NVFP4 的表示范围内。剪枝掩码把部分列置零、同时把误差补偿量 <span>δ_q</span> 加到保留列上，这一步会改变保留权重的动态范围与离群值位置；而 NVFP4 的块缩放（每 16 元素一个 FP8 scale）与 FP8 的 per-tensor／per-channel 缩放粒度是固定的。若剪枝后仍沿用剪枝前的缩放因子，补偿量可能被量化步长吞掉，层输出误差从 <span>‖WX−ŴX‖₂</span> 量级放大到量化噪声量级。工程判断是：剪枝掩码与量化缩放必须分别管理，先剪枝、再按剪枝后权重重新校准缩放，两步之间不能共用同一份统计。</p>\n<div class=\"formula\">$$\\hat{W}=\\arg\\min_{\\hat{W}}\\|WX-\\hat{W}X\\|_2^2,\\qquad \\hat{W}_{:,q}\\leftarrow \\hat{W}_{:,q}+\\delta_q,\\quad \\delta_q=-\\frac{w_q}{[H^{-1}]_{qq}}H^{-1}_{:,q}$$</div>\n<p>公式三项对应三个系统代价：<span>H</span> 是校准激活的输入二阶统计，其规模为层宽平方，在宽 FFN 层上存储与求逆是离线显存与算力开销，层越宽越贵；<span>[H^{-1}]_{qq}</span> 的对角元决定单列剪枝误差的放大倍数，对角元小的列剪掉代价低，这解释了为什么 OBS 优于按权重幅值剪枝；<span>δ_q</span> 是补偿向量，它把被剪列的误差摊到全部保留列上，使补偿后的权重出现新的非零模式——这正是与量化冲突的来源。校准阶段在多个时间步上累计 <span>H</span>，时间步覆盖不足时 <span>H</span> 只代表轨迹的一段，求逆得到的补偿方向在高噪段失效，表现为剪枝后早期去噪步的图像结构崩坏，而低噪段细节尚可，这种非均匀退化在只看最终 FID 时容易被平均掉。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>数值格式关注点</th><th>失效条件</th><th>代价归属</th></tr></thead><tbody><tr><td>校准累计 H</td><td>FP32 累加，避免 BF16 累加溢出</td><td>时间步覆盖窄</td><td>离线显存／算力</td></tr><tr><td>逐列补偿</td><td>补偿量需保留 FP32 精度再写回</td><td>补偿量落入量化步长</td><td>离线一次性</td></tr><tr><td>稀疏矩阵乘</td><td>FP8／NVFP4 块缩放需重校准</td><td>共用剪枝前缩放</td><td>在线每步时延</td></tr></tbody></table>\n<p>在线侧的实际收益只来自权重变小后的每步矩阵乘时延与权重显存占用，扩散主干没有 KV cache，显存节省不来自缓存复用。Blackwell 的 tcgen05 与 2-SM MMA 让大块矩阵乘的算力利用率提高，但这同时意味着当稀疏度不足以让矩阵乘落入更小的 tile 形状时，硬件仍按原 tile 调度，剪枝带来的算力节省会被 tile 对齐吃掉；稀疏度必须与 kernel 的 tile 粒度匹配才有吞吐收益。CFG 批合并把条件与非条件分支拼成一个批，剪枝不改变这一批形态，但批越大，每步时延对权重带宽越敏感，剪枝的收益越直接。结论落在一条可执行的边界上：把 OBS 校准与量化缩放校准拆成两次独立前向，用 FP32 保存补偿量，并在目标硬件档位上按 tile 粒度反推最小有效稀疏度，否则一次性剪枝的精度与吞吐收益都无法兑现。</p>\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-20\">二十 · 显存账本的三个账户：权重、激活、无 KV</h3>\n<p>在 Blackwell 上给扩散主干做容量规划，第一件事是把“显存”拆成可独立核算的三个账户，而不是笼统地看 <code>nvidia-smi</code> 的占用条。对 OBS-Diff 这类一次性剪枝方法，账本结构决定了收益落在哪一格：剪枝直接削减的是<b>权重账户</b>，间接影响<b>激活账户</b>的峰值，而<b>KV 账户在扩散主干上根本不存在</b>——这一点必须写死在预算表里，否则容量模型会系统性高估可压缩空间。DiT 的注意力是每步对当前潜变量做自注意力，序列长度由潜变量分辨率决定（例如 1024×1024 图像经 VAE 下采样后在潜空间是较小的 token 数），去噪步与步之间不保留任何跨步缓存；CFG 的条件与非条件分支通过批合并拼成一个批，同样不产生持久缓存。因此任何把 LLM 那套“KV cache 占大头”的经验搬到扩散推理上的估算都是错的。</p>\n<p>三个账户的量化方式如下。权重账户：<span class=\"formula\">$$M_{W} = N_{\\text{param}} \\times b_w$$</span>，其中 <span class=\"formula\">$$b_w$$</span> 是每参数字节数，BF16 为 2、FP8 为 1、NVFP4 为 0.5（外加按块缩放的元数据开销）。剪枝把 <span class=\"formula\">$$N_{\\text{param}}$$</span> 乘以保留率 <span class=\"formula\">$$(1-s)$$</span>，<span class=\"formula\">$$s$$</span> 为结构化列稀疏度；但稀疏掩码本身要存，若用位图则每参数约 <span class=\"formula\">$$1/8$$</span> 字节，非结构化稀疏在 Blackwell 的张量核心上还需额外索引，实际节省低于名义稀疏度。激活账户：峰值出现在单步前向的注意力与 FFN 中间张量，量级为 <span class=\"formula\">$$B \\times T \\times d \\times b_a \\times k$$</span>，<span class=\"formula\">$$B$$</span> 为批（含 CFG 合并后的双份）、<span class=\"formula\">$$T$$</span> 为潜变量 token 数、<span class=\"formula\">$$d$$</span> 为隐藏维、<span class=\"formula\">$$k$$</span> 为同时驻留的中间缓冲倍数。剪枝不改变 <span class=\"formula\">$$T$$</span> 与 <span class=\"formula\">$$d$$</span>，只可能因稀疏矩阵乘的累加器布局略改 <span class=\"formula\">$$k$$</span>，所以激活账户基本不动——这是部署侧最容易误判的一笔。</p>\n<p>具体例子：一个以 BF16 加载的 DiT 主干，若权重账户在剪枝加 FP8 后从 2 字节/参数降到约 1 字节/参数并叠加稀疏，单卡可容纳的批大小随之上升；但若激活峰值不变，批大小仍被激活账户卡住，收益就只体现在每步矩阵乘的算力下降而非并发提升。工程判断是：先算清哪个账户是约束边界，再决定剪枝、量化、批调度的投入顺序。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-21\">二十一 · HBM3e 容量怎么算：可用量不是标称量</h3>\n<p>B200/GB200 档位的 HBM3e 容量是容量规划的上界，但不是可用量。可复算的预算应写成：<span class=\"formula\">$$C_{\\text{avail}} = C_{\\text{HBM}} - C_{\\text{runtime}} - C_{\\text{frag}}$$</span>。其中 <span class=\"formula\">$$C_{\\text{runtime}}$$</span> 包含 CUDA context、通信缓冲（NCCL 的 all-reduce 桶、NVLink 5 上的 P2P 缓冲）、框架自身的 workspace 与图捕获占位；<span class=\"formula\">$$C_{\\text{frag}}$$</span> 是分配器碎片与预留，按经验比例留出，不能按 0 计。TensorRT-LLM、vLLM、SGLang 在启动时都会预分配 KV/激活池与 CUDA graph 捕获空间，这些在扩散服务里同样存在，只是池的内容不同。分离式预填/解码（PD 分离）在扩散上对应的是把 VAE 解码与 DiT 去噪分到不同实例，此时两侧的 HBM 预算要分别核算，VAE 侧的激活峰值与 DiT 侧不是一个量级。</p>\n<p>把预算写成表格形式最便于复核。以“单卡装下一个剪枝后的 DiT 主干并留出批余量”为目标，账本如下（数值为结构示意，具体档位按实际卡型代入）：</p>\n<table class=\"mini\">\n<thead><tr><th>账户</th><th>构成</th><th>随剪枝的变化</th><th>随量化的变化</th></tr></thead>\n<tbody>\n<tr><td>权重</td><td>参数 × 字节/参数 + 稀疏掩码</td><td>按保留率线性下降，掩码抵消一部分</td><td>FP8 减半，NVFP4 再减半并加缩放元数据</td></tr>\n<tr><td>激活峰值</td><td>批 × token × 隐藏维 × 缓冲倍数</td><td>基本不变</td><td>中间张量可降精度，但累加器仍需较宽</td></tr>\n<tr><td>运行时</td><td>context、通信桶、workspace、图捕获</td><td>不变</td><td>不变</td></tr>\n<tr><td>碎片与预留</td><td>分配器碎片、临时缓冲</td><td>不变</td><td>不变</td></tr>\n<tr><td>KV</td><td>无</td><td>无</td><td>无</td></tr>\n</tbody>\n</table>\n<p>这张表的价值在于暴露一个常见错误：把“权重减半”直接等同于“可服务批大小翻倍”。只有当权重账户是约束边界时该等式才近似成立；若激活峰值已经逼近 <span class=\"formula\">$$C_{\\text{avail}}$$</span>，权重缩小只释放了非约束账户的空间，批大小不变，吞吐提升仅来自每步时延下降。校准阶段的二阶统计矩阵（Hessian 近似）属于离线开销，其存储与求逆在层宽较大时占用可观显存，但它发生在压缩流水线里，不进在线预算——把这两笔混在一起算，会得出“剪枝很贵”的错误结论。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-22\">二十二 · 带宽瓶颈的位置：权重流与激活流是两条不同的路</h3>\n<p>推理每步的耗时由算力与带宽共同决定，Blackwell 上要分清瓶颈落在哪条流上。权重流：每步前向要把参与计算的权重从 HBM 搬到 SM，若批较小、算术强度低，这一步就是带宽受限，此时<b>权重字节数直接决定每步时延下限</b>，剪枝与量化叠加的收益最明显。激活流：注意力与 FFN 的中间张量在片上与 HBM 之间往返，token 数大、批大时这条流会压过权重流。判别方法用算术强度：<span class=\"formula\">$$\\text{AI} = \\frac{2 \\cdot B \\cdot T \\cdot d_{\\text{in}} \\cdot d_{\\text{out}}}{b_w \\cdot d_{\\text{in}} \\cdot d_{\\text{out}} + b_a \\cdot \\text{中间张量字节}}$$</span>，当 AI 低于硬件的 ops/byte 拐点时即为带宽受限。扩散推理的批通常不大（受激活峰值限制），因此大量线性层处在带宽受限区，这正是权重压缩类方法（剪枝、FP8/NVFP4）在扩散上有效的物理原因。</p>\n<p>伪代码思路：对每层估算 <span class=\"formula\">$$t_{\\text{layer}} \\approx \\max\\left(\\frac{\\text{FLOPs}}{\\text{Peak FLOPS}},\\ \\frac{\\text{Bytes}}{\\text{HBM BW}}\\right)$$</span>，把各层相加得到单步时延下界，再乘以步数得到请求延迟下界。剪枝改变的是 <span class=\"formula\">$$\\text{Bytes}$$</span> 中的权重项与 <span class=\"formula\">$$\\text{FLOPs}$$</span> 中的有效乘加数（稀疏矩阵乘在硬件上未必线性加速，取决于稀疏模式是否匹配张量核心的块结构），量化改变 <span class=\"formula\">$$b_w$$</span> 与 <span class=\"formula\">$$b_a$$</span>。这个模型不需要精确，它的用途是判断“再压权重还有没有用”：若某层已明显算力受限，继续剪该层只省显存不省时间。</p>\n<p>具体代价例子：一个带宽受限的线性层，权重从 BF16 降到 FP8 使每步该层的字节流减半，时延下界随之下降；若同时施加列稀疏但稀疏模式不被张量核心直接支持，需先解压/重排，反而引入额外带宽与指令开销，收益被吃掉。这就是“剪枝掩码与量化缩放需分别管理”的系统含义——两者叠加不是简单相乘，掩码布局必须与目标硬件的稀疏乘加路径对齐。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-23\">二十三 · 分页、压缩、复用、卸载：扩散侧各自对应什么</h3>\n<p>这四个词在 LLM 服务里各有明确所指，搬到扩散推理上要逐一重新定位，不能照搬。</p>\n<ul>\n<li><b>分页</b>：LLM 的分页针对 KV cache 的块管理；扩散主干无 KV，分页的价值转移到<b>激活池与批槽</b>的管理上——把激活缓冲按固定块分配、按请求生命周期回收，避免不同分辨率/不同批形态造成的碎片。CFG 批合并使批形态在条件与非条件之间固定为双份，分页粒度可按此对齐。</li>\n<li><b>压缩</b>：在扩散侧主要指权重压缩（剪枝 + FP8/NVFP4）与激活的降精度中间表示。剪枝属于一次性离线压缩，量化可在加载时反量化或按块缩放；两者叠加时缩放粒度与掩码必须分开验证，共用粒度会放大剪枝误差。</li>\n<li><b>复用</b>：跨步复用激活或中间特征在扩散上确有空间（相邻时间步的潜变量高度相关），但这类缓存复用属于另一条加速线（缓存类方法），与 OBS-Diff 的权重剪枝正交；本部分的账本只登记“复用带来的激活账户下降”，不展开其机制。</li>\n<li><b>卸载</b>：把不参与当前步的权重或 VAE 参数放到主机内存或对端，按需换入。扩散的步间权重集是固定的（每步都过整个主干），所以卸载的收益主要来自<b>多模型共存</b>场景——例如同一卡上驻留多个不同分辨率的 DiT 或 VAE 解码器，按请求切换。卸载的代价是 PCIe/NVLink 上的换入带宽，必须计入每步时延而非仅算容量。</li>\n</ul>\n<p>具体机制例子：VAE 解码与 DiT 去噪分离部署时，VAE 侧只在请求末尾激活，其权重可常驻主机并在解码前换入，DiT 侧则常驻 HBM；这样单卡的 HBM 预算只需覆盖 DiT 权重加激活峰值，VAE 的容量需求被移出关键路径。代价是解码阶段多一次换入延迟，对 SLO 中尾延迟敏感的场景要单独测量。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-24\">二十四 · 一个可复算的显存预算（含剪枝与量化叠加）</h3>\n<p>下面给出可直接代入的预算流程，读者把自家卡型的 HBM 容量、模型参数量、潜变量 token 数、批大小填进去即可复算。步骤一，确定约束账户：先按 BF16 原模型算权重账户与激活峰值，取较大者为约束；步骤二，施加剪枝保留率与量化字节数，重算权重账户；步骤三，检查激活峰值是否已成为新约束；步骤四，把运行时与碎片从 <span class=\"formula\">$$C_{\\text{HBM}}$$</span> 中扣除得到 <span class=\"formula\">$$C_{\\text{avail}}$$</span>；步骤五，用剩余空间反解可服务批大小，并与 SLO 要求的并发对比。</p>\n<div class=\"formula\">$$B_{\\max} = \\left\\lfloor \\frac{C_{\\text{avail}} - M_{W}(s, b_w)}{T \\cdot d \\cdot b_a \\cdot k} \\right\\rfloor$$</div>\n<p>其中 <span class=\"formula\">$$M_{W}(s,b_w) = N_{\\text{param}} \\cdot (1-s) \\cdot b_w + M_{\\text{mask}}$$</span>。这个式子的关键性质是：<span class=\"formula\">$$B_{\\max}$$</span> 对 <span class=\"formula\">$$s$$</span> 与 <span class=\"formula\">$$b_w$$</span> 的敏感度取决于 <span class=\"formula\">$$M_W$$</span> 在 <span class=\"formula\">$$C_{\\text{avail}}$$</span> 中的占比。若权重占比高，压缩直接换来批大小；若激活占比高，压缩只降低每步时延，批大小由分母锁死。</p>\n<p>具体例子：设某 DiT 主干在 BF16 下权重账户占据可用显存的主要部分，激活峰值在目标批下尚有余量；施加剪枝保留率与 FP8 后权重账户显著下降，<span class=\"formula\">$$B_{\\max}$$</span> 上升，吞吐随批线性增长直到激活峰值触顶。此时若继续加大稀疏度，权重账户已非约束，批不再增长，收益转为每步时延下降带来的单请求延迟改善——两条收益曲线在同一张预算表上分得很清楚。反过来，若一开始激活峰值就是约束，剪枝的容量收益为零，只应把它当作时延优化手段来评估投入产出。</p>\n<p>预算表还要登记一笔容易被忽略的成本：校准阶段的二阶统计矩阵按层存储，层宽为 <span class=\"formula\">$$d$$</span> 时单层矩阵为 <span class=\"formula\">$$d \\times d$$</span> 量级，逐层串行可把峰值压到单层规模，层内分块并行则需多份缓冲。这笔开销发生在离线压缩流水线，与在线服务容量无关，但决定了压缩任务本身能否在给定卡上跑完——容量规划应把“压缩流水线预算”与“在线服务预算”分成两张表，各自独立核算。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-25\">二十五 · 工程判断：账本先于手段</h3>\n<p>把上面的账本落到部署决策上，结论是顺序问题而非方法优劣问题。第一步永远是测出约束账户：用 BF16 原模型在目标批下跑一步前向，记录权重驻留、激活峰值与每步时延，判断该步是算力受限还是带宽受限。若权重账户是约束且该层带宽受限，剪枝叠加 FP8/NVFP4 是正确投入；若激活峰值是约束，应先动批调度与分辨率/潜变量 token 数，剪枝只作为时延手段；若两者都不是约束而尾延迟受 VAE 解码拖累，则应考虑卸载与 PD 分离而非继续压 DiT 权重。</p>\n<p>第二个判断点是稀疏度上限与量化叠加的验证顺序。剪枝掩码与量化缩放分别管理，意味着验证必须分三步：先验剪枝单独的质量漂移，再验量化单独的漂移，最后验叠加后的漂移；跳过中间步骤会把叠加误差误归因于某一方。校准时间步覆盖不足是主要失败模式，账本上表现为“离线统计不能代表整条采样轨迹”，在线表现为高噪或低噪段的生成质量退化——这类退化不会体现在显存与时延数字上，只能靠质量监控捕获，因此容量规划必须与质量漂移监控同表登记。</p>\n<p>第三个判断点是稀疏矩阵乘在 Blackwell 张量核心上的实际路径。名义稀疏度不等于时延收益，掩码布局若与硬件的块稀疏乘加不匹配，解压与重排的带宽开销会抵消权重流缩减。工程上应把“权重字节下降比例”与“实测每步时延下降比例”并列记录，两者的差额就是稀疏落地损耗；这个差额在多长时间步、多大分辨率下稳定，决定了该压缩方案能否进入常态化服务流水线。</p>\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-26\">二十六 · 剪枝模型的批形态：CFG 合并与稀疏权重的调度耦合</h3>\n<p>OBS-Diff 不改变采样器的批结构，这一点对调度设计是决定性的：剪枝只改权重，不改请求语义。文生图服务里最稳定的批形态来自 CFG 合并——把条件分支与非条件分支拼成同一个批送进 DiT 主干，一次前向同时算出两组预测。这意味着调度器看到的批大小是用户请求数的两倍，而剪枝后的线性层以稀疏权重参与矩阵乘，每步时延下降直接转化为批周转速度的提升。工程上要抓住的耦合点是：批越大，单步矩阵乘越接近算力饱和，剪枝省下的算力被更充分地利用；批越小，单步受权重带宽与 kernel 启动开销支配，剪枝降低的权重显存反而成为主要收益。因此剪枝模型的连续批处理不能沿用稠密模型的最优批上限，需要在同一 SLO 下重新扫描批大小。</p>\n<p>连续批处理的基本机制是迭代级调度：每个去噪步结束时检查队列，把完成的序列换出、把新请求换入，而不等整批采样结束。对扩散模型而言，一个请求的生命周期是固定的若干步（或蒸馏后的少步），步与步之间没有自回归式的变长输出，因此“换入换出”的粒度天然对齐到步边界。代价在于：批内序列的步数若不一致（例如混合了不同步数档位的请求），调度器必须按最大步数补齐或分组，补齐部分浪费算力。实践中的做法是按步数档位分桶，桶内做连续批处理，桶间共享 GPU 但不同批。稀疏权重使每步算力需求下降，桶的批上限可以上调，但上调幅度受激活显存约束——扩散主干无 KV cache，显存节省主要来自权重与激活，激活随批线性增长，这是批上限的硬边界。</p>\n<div class=\"formula\">$$T_{\\text{batch}} \\approx \\sum_{s=1}^{S} \\max_{i \\in \\mathcal{B}_s} t_{\\text{step}}(s, i), \\quad \\text{吞吐} = \\frac{|\\mathcal{B}| \\cdot S}{T_{\\text{batch}}}$$</div>\n<p>其中 $\\mathcal{B}_s$ 是第 $s$ 步的活跃批，$t_{\\text{step}}$ 是该步单序列时延。公式暴露的取舍是：批内步数不齐时，$\\max$ 取到最长者，短请求白等。剪枝降低 $t_{\\text{step}}$，直接压缩 $T_{\\text{batch}}$，但若批上限被激活显存卡死，吞吐增益会被截断。具体例子：一个 8 卡节点同时服务 20 步与 4 步两档请求，若不分桶，4 步请求要陪跑 16 步的空转；分桶后两档各自连续批处理，剪枝模型在 4 步桶里可以把批开得更大，因为少步采样的激活峰值更低。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-27\">二十七 · Chunked prefill 在扩散链路里的对应物：文本编码与 VAE 解码的分段</h3>\n<p>扩散模型没有 LLM 意义上的长 prefill，但链路上存在两个可分段的重活：文本编码器前向与 VAE 解码。文本编码器对提示做一次前向，长度随提示变化；VAE 解码把最终潜变量还原为图像，计算量与分辨率成正比。把这两段做成 chunked 式分段执行，目的是不让它们独占整卡、阻塞去噪主循环的批周转。机制上，调度器把文本编码与 VAE 解码放进独立的低优先级流，按固定 chunk 大小切分提示批与潜变量批，与 DiT 去噪步交错提交，利用去噪步之间的空隙填充。代价是流间同步点增加：VAE 解码必须在采样结束后才能启动，无法与最后几步重叠太多；文本编码则可以提前，因为提示在请求入队时就已知。</p>\n<p>分段带来的收益是尾延迟的削峰。一个请求的端到端时延由编码、$S$ 步去噪、解码三段构成，其中解码段对高分辨率请求可能占到可观比例。若解码与下一批的去噪争抢 SM，去噪步时延抖动会传导到所有在批请求上，形成队头阻塞。把解码切小片、限流提交，等价于给解码设一个带宽配额，让去噪主循环的步间隔保持稳定。工程判断是：分段粒度不宜过细，chunk 太小则 kernel 启动与流同步开销吃掉收益；经验上按解码单片的算力占单步去噪算力的比例来定，使每个 chunk 的提交不打断正在执行的去噪 kernel。这里没有论文给出的数字，只能定性：分段是尾延迟工具，不是吞吐工具，吞吐仍由批大小与每步时延决定。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-28\">二十八 · 优先级与抢占：SLO 分档下的批重组</h3>\n<p>多租户或混合负载场景里，请求带不同时延目标。调度器需要优先级队列加抢占：高优先级请求到达时，从低优先级批中腾出显存与算力槽位。扩散模型的抢占比自回归模型简单——没有 KV cache 需要换出到主机，被抢占的请求只需保存当前潜变量张量与步计数，恢复时从该步继续采样。这个状态很小（潜变量尺寸固定），换出成本远低于 LLM 的 KV 换出。机制上，抢占点设在步边界：当前步的 kernel 不打断，步结束后把低优先级序列移出活跃批，腾出的批槽给高优先级请求，下一批按新组成重新做 CFG 合并。</p>\n<p>代价出现在批重组本身：CFG 合并要求条件与非条件分支成对进出，抢占一个请求意味着它的两个分支同时移出，批形状改变会触发 kernel 重新选择与可能的显存重分配。频繁抢占会让批形状抖动，单步时延的方差上升，反而伤害高优先级请求的尾延迟。因此优先级设计要配合最小驻留时间：一个批一旦组成，至少跑若干步才允许被抢占，把重组频率压下来。具体例子：在线服务把请求分为交互档与批量档，交互档要求端到端时延上界，批量档只求吞吐；调度器给交互档预留固定批槽，批量档填充剩余槽位并在交互档到达时按步边界让位。剪枝模型在这里的作用是让预留槽位的单步时延更低，同等 SLO 下预留比例可以调小，把更多槽位让给批量档。</p>\n<p>尾延迟的压制还依赖一个常被忽略的机制：批内最慢序列决定步时延。CFG 合并后批内所有序列同步推进，任何一条序列的异常（例如提示触发的极端激活）都会拖慢整批。调度器可以用分位数监控识别长尾序列并单独成批，代价是牺牲该批的利用率换取整体步间隔的稳定。这是典型的吞吐换尾延迟，是否值得取决于 SLO 的严格程度。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-29\">二十九 · 分离式预填/解码在扩散上的映射：编码与去噪分离</h3>\n<p>LLM 的分离式预填/解码把计算密集的 prefill 与访存密集的 decode 放到不同资源池。扩散链路的对应划分是：文本编码（一次性、计算密集、批内长度不一）与去噪循环（固定步数、每步算力与权重带宽混合）分离到不同实例，中间通过高速互联传递提示嵌入。NVLink 5 与 NIXL 这类传输层在这里的作用是让嵌入张量的搬运不成为瓶颈——嵌入尺寸相对潜变量很小，传输开销可忽略，分离的收益主要来自资源配比：编码池可以用少量高算力卡应对突发提示洪峰，去噪池按稳态批容量配置，两池独立扩缩容。</p>\n<p>分离的代价是链路时延增加一跳与排队耦合：编码池的排队会推迟去噪池的入批时刻，端到端时延的方差被放大。工程上要把编码池的队列深度压到很小，宁可多配算力也不让编码成为排队点。另一个代价是故障域扩大，两池之间的传输失败需要重试语义。对剪枝模型而言，分离还有一个额外好处：去噪池加载的是剪枝后的稀疏权重，权重显存下降使单卡可容纳的批上限提高，去噪池的卡数可以少于稠密模型，资源配比向编码池倾斜。具体例子：一个部署把编码与去噪放在同一批卡上时，提示洪峰会挤占去噪步的 SM，造成步间隔抖动；分离后编码洪峰被隔离在另一池，去噪池的步间隔由批组成决定，尾延迟可控。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-30\">三十 · 时延与吞吐的取舍面：用剪枝收益换 SLO 余量</h3>\n<p>把上述机制放在一张取舍面上：横轴是批大小，纵轴是每步时延；吞吐是批大小除以每步时延的单调函数，而端到端时延随批大小上升。剪枝把整条曲线向下平移——每步时延在任意批大小下都更低，因此同一 SLO 下可以选更大的批，或同一批下获得更低的尾延迟。关键判断是收益落在哪一侧：若系统受算力约束（大批、算力饱和），剪枝省下的矩阵乘算力直接变成吞吐；若系统受权重带宽约束（小批、访存主导），剪枝降低权重显存与读取量，收益体现在单步时延与可容纳批上限上。两种情形的最优批大小不同，调度参数必须跟着剪枝后的实测曲线重扫，不能沿用稠密模型的配置。</p>\n<p>尾延迟的压制需要三个手段叠加：按步数档位分桶避免陪跑、按分位数把长尾序列单独成批、给解码段设带宽配额防止队头阻塞。三者都以牺牲部分利用率为代价，因此要在一个明确的 SLO 下量化：给定端到端时延上界，求最大可持续批组成。剪枝在这里提供的是余量而非免费午餐——它把每步时延压下来，让同样的尾延迟控制手段可以少牺牲一点利用率。校准成本与二阶统计求逆属于离线开销，不进入在线队列，这一点在容量规划时必须分开记账，否则会把离线一次性成本误摊到在线吞吐上。</p>\n<table class=\"mini\"><thead><tr><th>调度手段</th><th>主要收益</th><th>主要代价</th><th>与剪枝的耦合</th></tr></thead><tbody><tr><td>连续批处理（分桶）</td><td>减少批内陪跑，提升稳态吞吐</td><td>桶间 GPU 共享带来形状抖动</td><td>批上限受激活显存约束，剪枝不放松该约束</td></tr><tr><td>chunked 分段（编码/解码）</td><td>削尾延迟峰，稳定步间隔</td><td>流同步与 kernel 启动开销</td><td>解码算力不变，剪枝只缩短去噪段</td></tr><tr><td>优先级与抢占</td><td>保障高优先级 SLO</td><td>批重组抖动，需最小驻留时间</td><td>单步时延下降使预留槽位可缩小</td></tr><tr><td>分离式编码/去噪</td><td>资源配比独立扩缩容</td><td>多一跳传输与排队耦合</td><td>去噪池卡数可减少，配比向编码倾斜</td></tr></tbody></table>\n<p>工程判断落在具体机制上：调度参数的重扫必须绑定剪枝后的实测每步时延曲线，而不是绑定稀疏度数字。稀疏度高不等于每步快——稀疏权重的矩阵乘是否真正提速取决于硬件对稀疏格式的支持与 kernel 实现，若稀疏未被硬件路径利用，收益只剩权重显存下降。因此容量规划的顺序是：先测剪枝模型在目标批大小下的每步时延与激活峰值，再定桶划分与预留槽位比例，最后才谈吞吐目标。CFG 合并的批形态在这一步不能省，因为它决定了调度器看到的真实批大小与算力饱和度。</p>\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-31\">三十一 · 从单卡校准到多卡切分：剪枝模型的并行拓扑约束</h3>\n<p>OBS-Diff 的产物是一份带掩码的稀疏权重，但这份权重落到 Blackwell 机架上时，必须回答一个前置问题：它按什么拓扑切分。DiT 主干的线性层在 B200 单卡上尚可容纳，一旦进入 GB200 NVL72 级别的部署，TP（张量并行）、EP（专家并行）、PP（流水并行）、DP（数据并行）四种切分方式对剪枝结果的敏感度完全不同。TP 切分的是同一层的权重矩阵列或行，剪枝掩码必须与切分边界对齐，否则某一 rank 上的稀疏列分布不均，导致该 rank 的矩阵乘有效算力被浪费；EP 切分的是 MoE 或条件分支，剪枝若按全局列重要性排序，会把重要性高的列集中到某个专家，破坏负载均衡；PP 切的是层，剪枝逐层独立进行，天然适配 PP，但层间激活的 dtype 与量化缩放必须在 stage 边界统一；DP 复制完整权重，剪枝掩码在所有副本上一致，代价是每张卡都承担同样的权重显存，剪枝带来的显存节省被复制放大。</p>\n<p>工程判断的落点是：剪枝掩码的生成必须在目标并行拓扑确定之后进行，或至少按拓扑约束重新排列列索引。一个具体机制是把 OBS 的逐列补偿顺序与 TP 的列分块边界绑定——每个 TP rank 只对属于自己列块的子矩阵求 <span>H</span> 逆并选列，层内按列分块并行正是材料中提到的校准并行方式。代价是：TP 度数为 <span>t</span> 时，单层二阶统计矩阵的求逆被切成 <span>t</span> 份，单卡显存开销降为 <span>1/t</span>，但跨 rank 的列重要性无法全局比较，稀疏度上限受最不均 rank 约束。以 8 路 TP 的 DiT 为例，若某 rank 的列块在高噪时间步上激活方差偏小，其可剪列数少于其他 rank，整层稀疏度被这一 rank 拖住。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-32\">三十二 · NVLink 5 与 NVSwitch：集合通信的带宽账</h3>\n<p>Blackwell 世代的 NVLink 5 与 NVSwitch 把单机架内的 GPU 间带宽推到远高于 PCIe 的水平，NVL72 把 72 颗 GPU 纳入同一 NVLink 域。对推理而言，这意味着 TP 与 EP 的集合通信不再必然走主机网络，All-Reduce 与 All-to-All 可以在 NVLink 域内完成。但带宽高不等于通信免费：TP 的每层前向需要两次 All-Reduce（注意力输出与 FFN 输出各一次），通信量与激活大小成正比，与权重稀疏度无关。剪枝降低的是权重显存与矩阵乘算力，却不会减少 TP 的 All-Reduce 字节数——激活的宽度由隐藏维度决定，剪枝掩码不改变它。</p>\n<div class=\"formula\">$$T_{\\text{comm}} \\approx \\frac{2 \\cdot B \\cdot S \\cdot H \\cdot b}{W_{\\text{nvl}}} \\cdot \\frac{t-1}{t}$$</div>\n<p>其中 <span>B</span> 为批大小，<span>S</span> 为序列长度，<span>H</span> 为隐藏维度，<span>b</span> 为每元素字节数，<span>W</span> 为 NVLink 有效带宽，<span>t</span> 为 TP 度数。这个式子给出一个直接推论：剪枝把每步矩阵乘时间压下去之后，All-Reduce 在每步总时延中的占比上升，通信成为瓶颈的临界点被剪枝本身推近了。具体例子：一个原本矩阵乘占每步 70% 时延的 DiT，剪枝后矩阵乘降到 40%，若 All-Reduce 绝对时间不变，其占比从 30% 升到 60% 量级，此时继续提高稀疏度对端到端时延的边际收益迅速衰减。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-33\">三十三 · All-to-All 与 EP：扩散主干里最贵的通信形态</h3>\n<p>EP 用于 MoE 结构的 DiT 变体，其通信形态是 All-to-All：每个 rank 把 token 按路由结果发给持有对应专家的 rank，算完再发回。All-to-All 的通信量取决于路由的分散程度，最坏情况下每个 token 都要跨 rank 往返一次，字节数为 <span>\\(2 \\cdot B \\cdot S \\cdot H \\cdot b\\)</span> 乘以路由扇出。与 All-Reduce 不同，All-to-All 对负载均衡极度敏感：某个专家收到的 token 偏多，其所在 rank 成为木桶短板，其余 rank 在等待。剪枝在这里的作用是双刃的——它压缩了专家权重的显存占用，使更多专家能驻留同一 GPU，减少跨 rank 扇出；但若剪枝按全局重要性排序，会把高重要性列推向少数专家，加剧路由倾斜。</p>\n<p>推理系统的代价体现在尾延迟而非平均吞吐：扩散采样是串行步进，每一步都被最慢的 rank 卡住，All-to-All 的不均衡直接转化为每步时延的方差。一个可操作的机制是在剪枝校准阶段同时记录每个专家列的激活频次，把频次作为路由均衡的约束项加入列选择，使剪枝后的专家负载分布不劣化。这属于离线校准的额外统计开销，不进入在线链路。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-34\">三十四 · PP 与 DP：剪枝收益被稀释与放大的两种方式</h3>\n<p>PP 把层切成 stage，stage 间只传激活，通信量小但存在流水气泡。扩散采样的每一步都要走完整条流水线，气泡在步与步之间无法被后续请求填满——除非调度器把多个请求的采样步交错排布，这正是连续批处理在扩散场景的变体。剪枝对 PP 的影响是中性的：每层权重变小，stage 内矩阵乘变快，但 stage 间激活传输字节不变，气泡占比相对上升。PP 度数越深，气泡代价越显著，剪枝带来的单 stage 加速被流水线启动开销吃掉的比例越高。</p>\n<p>DP 则是另一回事：每个副本持有完整权重，剪枝掩码在副本间必须一致以保证输出可复现。DP 的通信只在梯度场景有意义，推理侧 DP 基本无集合通信，代价全在显存复制上。剪枝把单副本权重显存降低，但 <span>d</span> 个副本的总显存仍为 <span>d</span> 倍，剪枝节省被线性放大为集群级显存节省——这是 DP 下剪枝最直接的收益。具体例子：一个 DP=4 的部署，单副本权重从可观测量级压缩后，集群总权重显存按 4 倍同步下降，而每副本的 All-Reduce 开销为零，此时剪枝是纯粹的容量收益，不引入通信副作用。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-35\">三十五 · NIXL 传输：分离式预填/解码下的权重与激活搬运</h3>\n<p>分离式架构把预填与解码拆到不同 GPU 池，扩散推理的对应形态是把 VAE 解码、文本编码与 DiT 主干分置。NIXL 作为点对点传输层，负责在这些池之间搬运激活、潜变量与权重分片。剪枝在这里引入一个新的搬运对象：稀疏掩码与按块量化的缩放因子。掩码若以位图形式随权重一起传输，其字节数远小于权重本身，但需要接收端按掩码重建稠密布局或直接走稀疏内核；若接收端不支持稀疏内核，掩码传输就是纯开销。</p>\n<p>通信成为瓶颈的判据在分离式场景更清晰：当 DiT 主干的每步计算时间被剪枝与量化压到与一次 NIXL 传输潜变量的时间同量级时，传输延迟直接暴露在采样步的关键路径上。扩散采样每步都要把潜变量在组件间传递，步数越多，传输次数越多，这条路径的累积代价随步数线性增长。工程上的应对是把传输与计算重叠——下一步的潜变量传输与当前步的 DiT 计算并行——但这要求组件间有双缓冲潜变量，显存开销增加一份潜变量大小，与剪枝节省的权重显存形成对冲。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-36\">三十六 · 通信何时成为瓶颈：一个可计算的判据</h3>\n<p>把上述形态收拢为一个判据：设每步计算时间为 <span>\\(T_{\\text{comp}}\\)</span>，每步集合通信时间为 <span>\\(T_{\\text{comm}}\\)</span>，则通信成为瓶颈的条件是 <span>\\(T_{\\text{comm}} / (T_{\\text{comp}} + T_{\\text{comm}})\\)</span> 超过设定阈值，或更直接地，剪枝带来的计算时间下降量 <span>\\(\\Delta T_{\\text{comp}}\\)</span> 小于因占比上升导致的调度损失。剪枝把 <span>\\(T_{\\text{comp}}\\)</span> 压低，分母变小，同一 <span>\\(T_{\\text{comm}}\\)</span> 的占比被动上升——这意味着剪枝的收益曲线在某个稀疏度之后变平，拐点由并行拓扑与互联带宽共同决定，而非由剪枝算法本身决定。</p>\n<table class=\"mini\"><thead><tr><th>切分方式</th><th>每步通信形态</th><th>剪枝的影响</th><th>瓶颈判据</th></tr></thead><tbody><tr><td>TP</td><td>两次 All-Reduce</td><td>计算变快，通信字节不变，占比上升</td><td>激活字节 × 步数 / 带宽 与压缩后矩阵乘时间比较</td></tr><tr><td>EP</td><td>All-to-All</td><td>权重显存降、扇出可变，均衡敏感</td><td>最慢 rank 的 token 数与专家容量比较</td></tr><tr><td>PP</td><td>stage 间激活</td><td>单 stage 加速，气泡占比上升</td><td>气泡时间与 stage 计算时间比较</td></tr><tr><td>DP</td><td>无集合通信</td><td>显存节省按副本数放大</td><td>无通信瓶颈，纯容量收益</td></tr></tbody></table>\n<p>具体到 OBS-Diff 的部署判断：校准阶段在单卡或少量卡上完成，二阶统计的存储与求逆是离线开销，与在线通信无关；在线侧真正要盯的是剪枝后每步的 <span>\\(T_{\\text{comp}}\\)</span> 与 <span>\\(T_{\\text{comm}}\\)</span> 之比。若部署采用 TP=8 且 NVLink 域内 All-Reduce 已经很快，剪枝的收益能完整落到端到端时延上；若采用跨机架 TP 或 EP 扇出较大，剪枝把计算压得越狠，通信占比越高，此时应优先考虑降低 TP 度数、把权重放回单卡、用 DP 换容量，而不是继续加稀疏度。剪枝掩码与量化缩放分别管理这一约束也适用于通信：掩码决定哪些列不参与计算，缩放决定传输字节的精度，两者在 stage 边界必须一致，否则接收端要么多传冗余位、要么精度对不上。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-37\">三十七 · 剪枝与并行拓扑的耦合边界：通信何时反噬收益</h3>\n<p>OBS-Diff 的剪枝发生在权重维度上，因此它与并行切分的交互点不在算子内部，而在切分后的层宽上。TP 把每层权重按列或行切开，EP 把专家分散到不同 rank，PP 把层段分到不同 stage，DP 只复制副本。剪枝对 TP 的影响最直接：二阶统计矩阵的求逆开销随层宽平方增长，TP 切分后单卡上的层宽变小，离线校准的显存峰值随之下降，但代价是每层的剪枝决策必须在切分后的局部权重上完成，跨 rank 的列选择需要一次 All-Gather 汇总掩码，否则各 rank 独立剪枝会破坏层输出的整体误差补偿。对 EP 而言，剪枝掩码若按专家粒度独立生成，专家间的负载均衡会被稀疏度差异打破，All-to-All 的 token 分发出现长尾；对 PP 而言，剪枝不改变 stage 边界，但会改变每 stage 的计算时长，流水线气泡比例随各 stage 稀疏度不均而上升。</p>\n<p>通信成为瓶颈的判据可以用一个简单的比值刻画。设单层矩阵乘在剪枝后的有效算力时间为 <span class=\"inline-math\">T<sub>mma</sub></span>，一次集合通信的耗时为 <span class=\"inline-math\">T<sub>comm</sub> = S/B<sub>eff</sub> + L</span>，其中 S 为消息字节数、B<sub>eff</sub> 为有效带宽、L 为固定延迟。当剪枝把 T<sub>mma</sub> 压到与 T<sub>comm</sub> 同量级时，通信占比上升：</p>\n<div class=\"formula\">$$\\rho = \\frac{T_{\\text{comm}}}{T_{\\text{mma}} + T_{\\text{comm}}},\\quad \\text{剪枝使 } T_{\\text{mma}} \\downarrow \\Rightarrow \\rho \\uparrow$$</div>\n<p>这意味着稀疏度越高，TP 组内每层后接的 All-Reduce 越难被计算掩盖。NVLink 5 与 NVSwitch 提供的是机柜内高带宽域，跨节点则落到 NIXL 传输路径上，后者适合 KV 与权重的点对点搬运而非高频小消息同步。工程判断是：在 NVL72 域内，TP 的 All-Reduce 仍可被计算重叠吸收；一旦 TP 组跨出 NVLink 域，剪枝带来的算力节省会被通信延迟吃掉，此时应优先缩小 TP 度、改用 EP 承载稀疏化后的专家并行，或把剪枝掩码的汇总做成离线一次性产物而非在线同步。</p>\n<table class=\"mini\"><thead><tr><th>切分方式</th><th>剪枝引入的额外通信</th><th>失效条件</th></tr></thead><tbody><tr><td>TP</td><td>掩码 All-Gather、层后 All-Reduce</td><td>TP 跨 NVLink 域，ρ 接近 1</td></tr><tr><td>EP</td><td>All-to-All token 分发</td><td>专家稀疏度不均导致长尾</td></tr><tr><td>PP</td><td>stage 间激活传递</td><td>各 stage 稀疏度差异放大气泡</td></tr><tr><td>DP</td><td>无梯度同步（推理侧）</td><td>副本间掩码不一致</td></tr></tbody></table>\n<p>具体到一个 GB200 NVL72 上的文生图服务：剪枝后的 DiT 若以 TP=8 部署在单机柜内，CFG 批合并把条件与非条件分支拼成一个批，每步前向的 All-Reduce 消息量随批大小线性增长，而剪枝只降低了矩阵乘时间，消息量不变，因此大 batch 下 ρ 反而更有利、小 batch 低延迟场景下 ρ 更危险。若把同一模型拆到两个机柜做 TP=16，跨域链路使 L 显著上升，剪枝省下的每步时延被同步开销抵消，SLO 的尾延迟先崩。这里的系统代价不是显存而是带宽与同步等待：剪枝减少了权重显存与算力，却把并行拓扑的通信预算相对放大，部署时必须把稀疏度、TP 度与域边界三者一起定，而不是先剪枝再选拓扑。</p>\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-38\">三十八 · 精度塌陷的三种形态与时间步归因</h3>\n<p>OBS-Diff 的精度失败很少表现为“整张图全糊”，而是按采样轨迹分段显形，这决定了诊断必须带时间步坐标。第一种形态是<strong>高噪段塌陷</strong>：校准时间步偏向低噪区间时，二阶统计 $H$ 主要反映小信噪比下的激活协方差，剪枝列在高噪段被误判为“低贡献”，早期去噪步丢失结构先验，输出呈现构图漂移、主体位置错乱。第二种是<strong>低噪段塌陷</strong>：高噪覆盖不足的反面，末几步纹理与细节出现块状伪影，因为细粒度激活方向被剪掉后无法由剩余权重补偿。第三种是<strong>全轨迹均匀退化</strong>，通常不是剪枝本身，而是剪枝掩码与 FP8／NVFP4 缩放粒度冲突——掩码把权重置零后，按块缩放的分母仍按原块统计，反量化后残差被放大。</p>\n<p>归因手段是把每个采样步的输出潜变量与未剪枝基线做逐 step 的 $L_2$ 相对误差，画成“误差-时间步”曲线：若误差在 $t$ 接近纯噪端陡升，指向校准覆盖不足；若在 $t$ 接近零端抬升，指向逐层补偿在低噪激活上失配；若曲线整体平移，先查量化叠加。公式上，逐层重建的最优性条件是 $\\delta_q = -\\frac{w_q}{[H^{-1}]_{qq}}H^{-1}_{:,q}$，其中 $H$ 由校准激活累计；一旦 $H$ 的采样分布偏离线上轨迹，这个补偿方向本身就是错的，误差不会在层输出上最小化。工程代价上，逐 step 误差曲线只需一次前向对比，显存开销是两份潜变量序列，可忽略；但若不做，团队往往把精度塌陷误判为“稀疏度太高”，盲目降稀疏度，反而丢掉本可保留的压缩收益。</p>\n<ul>\n<li>具体机制：校准时间步按敏感度分层采样，高噪与低噪各占配额，避免单段主导 $H$。</li>\n<li>系统代价：逐 step 误差监控增加一次基线前向，延迟可摊到离线验证，不进在线链路。</li>\n<li>具体例子：文生图请求在 $t$ 高位出现主体缺失，回查校准集发现时间步集中在末段，补采高噪步后恢复。</li>\n</ul>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-39\">三十九 · OOM 的两个来源：二阶统计与激活峰值</h3>\n<p>部署侧最容易混淆的是把校准期 OOM 当成在线 OOM。OBS-Diff 的二阶统计矩阵按层累计，层宽 $d$ 对应 $d\\times d$ 的 $H$ 及其求逆，存储与求逆开销随层宽平方增长；在宽 FFN 层上，单层 $H$ 的显存可能超过该层权重本身。这是<strong>离线成本</strong>，不进入在线请求路径，但会决定校准能否在给定卡型上完成。缓解手段是层间串行、层内按列分块累计与分块求逆，把峰值压到单块 $H$ 的规模；代价是校准墙钟时间变长，因为分块求逆的算力利用率低于整矩阵分解。</p>\n<p>在线 OOM 则来自另一条路径：剪枝降低权重显存，但激活峰值由批大小与 CFG 批合并形态决定，剪枝不改变这部分。CFG 把条件与非条件分支拼成一个批，等效批翻倍，激活显存随之翻倍；若团队按“权重变小了”去放大批，激活先撞墙。诊断方法是分别记录权重占用、激活峰值与碎片化预留，看 OOM 发生在加载后还是首个去噪步——加载即 OOM 指向权重与量化反量化缓冲，首步 OOM 指向激活与 CFG 批形态。显存节省的正确预期是：扩散主干无 KV cache，节省来自权重与激活，缓存类手段在此不适用。</p>\n<div class=\"formula\">$$ \\text{peak}_{\\text{calib}} \\approx \\max_{\\ell}\\left( \\text{size}(H_\\ell) + \\text{size}(H_\\ell^{-1}) \\right),\\quad \\text{peak}_{\\text{online}} \\approx \\text{weights} + B_{\\text{cfg}}\\cdot \\text{act}_{\\text{step}} $$</div>\n<ul>\n<li>具体机制：分块累计 $H$ 并按块求逆，避免整层 $d\\times d$ 矩阵同时驻留。</li>\n<li>系统代价：校准显存峰值下降，但求逆算力效率下降，离线时间拉长。</li>\n<li>具体例子：宽 FFN 层校准 OOM，改为按列分块后单卡可完成，在线批大小不变。</li>\n</ul>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-40\">四十 · 批抖动与尾延迟：剪枝不改变批形态</h3>\n<p>剪枝模型沿用原采样器与 CFG 批合并策略，因此批抖动根因通常不在剪枝，而在调度层：请求到达率波动导致批在“拼批—等待—超时”之间反复，CFG 拼批又让有效批大小呈阶梯跳变。表现是每步矩阵乘时延随批大小非线性上升，尾延迟被少数大批拖长。诊断要区分两种抖动：<strong>批组成抖动</strong>（同一批内序列长度或分辨率差异大，导致 padding 浪费）与<strong>批大小抖动</strong>（调度器在吞吐与延迟目标间摇摆）。前者靠分桶与长度对齐缓解，后者靠固定最大批与排队上限约束。</p>\n<p>剪枝对尾延迟的贡献是单向的：权重变小后每步矩阵乘算力下降，单步时延下移，但尾延迟的方差主要来自批形态与显存压力，剪枝不会自动收窄方差。若叠加 FP8／NVFP4，反量化或按块缩放路径可能引入额外的每步开销，在小批时占比更高，表现为“小批不降反升”。监控应记录每步时延的 p50 与 p99 之差，并关联当步批大小；若 p99 抬升而 p50 下降，优先查批组成而非剪枝。伪代码思路：对每个去噪步打点 (batch_size, step_latency, mem_reserved)，按批大小分桶统计分位数，定位时延拐点对应的批阈值。</p>\n<ul>\n<li>具体机制：CFG 拼批把两分支合成一批，批大小阶梯化，调度需按拼批后的有效批设上限。</li>\n<li>系统代价：尾延迟由批形态主导，剪枝只降低均值，不保证 p99。</li>\n<li>具体例子：分辨率混批导致 padding 占比高，p99 抬升，改为分桶后回落。</li>\n</ul>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-41\">四十一 · 静默降级：没有报错的质量漂移</h3>\n<p>最危险的不是崩溃，而是服务正常返回、指标全绿、画质已降。静默降级在 OBS-Diff 部署中有三条典型路径：校准集与线上提示分布偏移，导致 $H$ 代表性不足而剪枝误差被低估；剪枝掩码与量化缩放分别管理时版本错配，掩码更新了而缩放表未同步；稀疏度在配置里被调高但未重跑校准，掩码与统计不匹配。三者都不触发异常，只表现为生成质量缓慢下滑或特定提示类型失败率上升。</p>\n<p>监控必须建立<strong>质量代理指标</strong>而非只看服务指标：对固定提示集定期跑基线对比，记录逐 step 潜变量误差与最终图像的结构相似度类指标；对线上流量按提示长度、类型分桶抽样人工或自动打分。定位手段是“掩码-缩放-校准”三元组版本绑定：每次剪枝产出物携带校准时间步清单、稀疏度与量化缩放版本，加载时校验一致性，不一致即拒绝上线而非静默运行。回滚策略要分层：质量漂移先回滚量化叠加层（保留剪枝），若仍漂移再回滚剪枝掩码到上一版，最后回退到未剪枝主干；每层回滚对应不同的显存与吞吐代价，需在容量规划里预留未剪枝主干的显存档位作为兜底。</p>\n<ul>\n<li>具体机制：剪枝产出物与校准时间步清单、量化缩放版本绑定，加载时校验。</li>\n<li>系统代价：保留未剪枝主干作回滚兜底，占用额外权重显存。</li>\n<li>具体例子：掩码更新后缩放表未同步，画质轻微劣化，版本校验拦截上线。</li>\n</ul>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-42\">四十二 · 回滚与容量兜底的具体判断</h3>\n<p>回滚不是运维动作的同义词，它需要容量侧预先买单。剪枝带来的权重显存节省若被全部用于放大批或提高并发，就失去了回滚空间；正确做法是把节省的一部分留作“未剪枝影子副本”的显存预算，仅在质量告警时启用。影子副本不必常驻计算，可放在低速存储按需加载，代价是回滚时的加载延迟，需在 SLO 里定义可接受的回滚窗口。另一个判断点是稀疏度上限：材料未给出定量稀疏度与 FID 数据，因此上线前必须在目标硬件档位与 SLO 下实测，把“稀疏度-质量-时延”三点做成可查询的表，而不是凭单点配置拍板。</p>\n<p>与量化叠加的回滚顺序也有讲究：剪枝误差与量化误差在层输出上叠加，若共用缩放粒度会放大残差，因此验证时必须分别跑“仅剪枝”“仅量化”“剪枝加量化”三组，任何一组不达标都不应上线组合配置。诊断脚本应能在一次校准产出后自动生成这三组对比的逐 step 误差曲线，把失败模式定位到具体层与具体时间步区间。最终落在工程判断上：OBS-Diff 的收益是离线一次性压缩换在线每步时延下降，它的失败模式几乎全部集中在“校准代表性”与“叠加配置一致性”两处，监控与回滚的设计应围绕这两点，而不是围绕稀疏度数字本身。</p>\n<ul>\n<li>具体机制：三组对比（仅剪枝／仅量化／叠加）逐 step 误差曲线自动生成。</li>\n<li>系统代价：影子副本与三组验证增加离线算力与存储，换回滚确定性。</li>\n<li>具体例子：叠加配置在某时间步区间误差抬升，定位到共用缩放粒度的层，拆分后恢复。</li>\n</ul>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-43\">四十三 · 校准偏差与静默降级的诊断闭环</h3>\n<p>OBS-Diff 最危险的失效不是崩溃，而是静默降级：服务不报错、显存不溢出、每步时延甚至更快，但生成质量在特定提示或特定噪声区间上塌陷。根因在二阶统计的代表性——校准阶段只在少数时间步上前向，若这些步集中在低噪段，高噪段的激活协方差被低估，逐列补偿量 δ_q = −w_q/[H⁻¹]_qq · H⁻¹_:,q 便按错误的曲率放大或缩小，剪枝误差在层输出上不再最小。诊断手段是把校准覆盖当作可观测指标：按噪声区间分桶记录每层激活的迹与条件数，若某桶样本数低于阈值或 H 近似接近奇异，该层剪枝应降级为保守掩码或跳过。代价是离线校准的显存与算力——层宽越大，二阶矩阵存储与求逆越贵，这属于一次性成本，不能摊到在线 SLO 上。</p>\n<p>在线侧需要三类探针并行：质量漂移（固定提示集的输出与剪枝前基线的感知距离或统计矩偏移）、批抖动（CFG 批合并后条件与非条件分支拼批，剪枝不改变批形态，但权重变小会改变每步时延分布，需监控 P99 而非均值）、以及尾延迟（VAE 解码与采样循环串联，任一段抖动都会放大）。定位顺序建议自后向前：先确认 VAE 与采样器未变，再比对剪枝层输出与原始层的相对误差，最后回到校准桶找缺失的时间步。回滚粒度应落在层与掩码上——保留剪枝前的权重快照与掩码版本号，按层回退比整模型回滚便宜得多。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>定位手段</th><th>回滚粒度</th></tr></thead><tbody><tr><td>精度塌陷</td><td>固定提示集统计矩偏移</td><td>逐层输出相对误差比对</td><td>按层恢复掩码</td></tr><tr><td>OOM</td><td>校准期二阶矩阵峰值显存</td><td>分块求逆、层内列分块</td><td>降低校准批或跳过宽层</td></tr><tr><td>批抖动/尾延迟</td><td>每步时延 P99 与批利用率</td><td>CFG 拼批形态核对</td><td>回退至未剪枝权重</td></tr><tr><td>量化叠加放大</td><td>FP8/NVFP4 缩放与掩码冲突</td><td>掩码与缩放分别验证</td><td>先撤量化再撤剪枝</td></tr></tbody></table>\n<p>与 FP8／NVFP4 叠加时，掩码与量化缩放必须分别管理：共用缩放粒度会让被剪列附近的保留权重落入同一量化桶，放大补偿误差，形成“剪枝看似成功、量化后塌陷”的复合失效。工程判断是：把剪枝与量化当作两条独立可回滚的变更线，先单独验证剪枝后的质量漂移，再叠加量化并复测同一批探针；任何一项探针越界即按上表回滚，而不是靠调批大小掩盖。</p>\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-44\">四十四 · 为什么这套基准必须先把口径钉死</h3>\n<p>OBS-Diff 的论文卡没有给出任何可核验的定量结果：稀疏度、FID、吞吐、显存占用全部缺失，硬件档位、基线方法名称、数据集名称同样未列出。这意味着任何“剪枝后快了多少”的说法都无法从材料直接引用，只能由部署方在自己的 Blackwell 档位上重建一套口径。口径不统一，数字就会互相污染：同一份剪枝权重，在 B200 单卡、GB200 NVL72 机柜、不同 batch 与并发下测出的每步时延可以相差数倍，而这些差异与剪枝方法本身无关。因此本部分不评价 OBS-Diff 快或慢，而是给出“怎么测、怎么读、哪些提升不可比”的判定规则。</p>\n<p>需要先明确一件事：OBS-Diff 是离线压缩步骤，校准与二阶统计求逆不进入在线请求队列。在线侧唯一能受益的是权重变小后每步矩阵乘的时延下降与权重显存占用下降。任何把校准耗时算进在线 TPOT 的报表都是错的；反过来，只报在线收益而不报校准成本，也无法判断这条压缩路径在容量规划上是否划算。基准表必须把离线成本与在线收益分成两栏。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-45\">四十五 · 模型与硬件档位：三组变量必须固定</h3>\n<p>第一组变量是主干形态。方法作用于 DiT／UNet 类扩散主干中的线性层与卷积层，层宽直接决定二阶统计矩阵的尺寸与求逆开销。层宽越大，离线校准的显存与算力开销越高，这是离线成本而非在线成本，但它决定了校准能否在单卡上完成。第二组是采样器与步数：剪枝模型沿用原采样器，按原步数或蒸馏步数执行去噪；步数不同，每请求的主干调用次数不同，TTFT 与 TPOT 的构成完全不同，跨步数比较吞吐没有意义。第三组是精度路径：剪枝后权重可叠加 FP8／NVFP4，缩放粒度与反量化路径材料未给出，因此“剪枝 + 量化”的精度损失必须单独验证，不能把纯剪枝的数字与剪枝加量化的数字放进同一张对比表。</p>\n<p>硬件档位同理要写死。B200 与 GB200 NVL72 的差别不只是单卡算力，还包括 NVLink 5 域内的通信形态与可用的并行拓扑；单卡测出的每步时延不能外推到 NVL72 机柜内的多卡并行配置。材料明确未给出硬件档位，所以任何报表都必须自报档位：卡型、卡数、并行切分方式、是否启用 FP8／NVFP4、是否使用 CFG 批合并。缺一项，这行数字就不可比。</p>\n<div class=\"formula\">$$\\text{每请求主干调用次数} = S \\times (1 + [\\text{CFG 启用}]),\\quad \\text{其中 } S \\text{ 为去噪步数}$$</div>\n<p>这个式子说明为什么 batch 与 CFG 必须一起报：CFG 通过把条件与非条件分支拼成一个批提高利用率，剪枝不改变该批形态，但批大小翻倍会改变每步矩阵乘的形态与显存峰值。只报“batch=8”而不说是否含 CFG 拼批，等于没报。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-46\">四十六 · batch、并发与指标定义</h3>\n<p>扩散推理没有 KV cache，显存节省主要来自权重与激活，因此显存口径要分“权重常驻”与“激活峰值”两项，不能只报一个总数。权重常驻在剪枝后按稀疏掩码与量化缩放分别管理，掩码本身也占显存；激活峰值随 batch 与分辨率线性上升，CFG 拼批会让峰值翻倍。基准表若只给一个显存数字，读者无法判断瓶颈在权重还是激活。</p>\n<p>指标定义要区分四类。TTFT 在扩散场景里对应首个去噪步完成到首块潜变量可解码的时间，受预填与首步矩阵乘支配；TPOT 对应后续每步时延，直接反映剪枝后每步算力下降；吞吐按“每秒完成请求数”或“每秒生成图像数”计，必须注明分辨率与步数；功耗则要注明是整机还是单卡、是否包含 VAE 解码。四类指标里，只有 TPOT 与吞吐能直接体现剪枝的在线收益，TTFT 的改善幅度取决于首步是否被权重加载与量化反量化支配。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>受什么支配</th><th>剪枝能否改善</th><th>报表必须附带</th></tr></thead><tbody><tr><td>TTFT</td><td>首步矩阵乘、权重加载、量化反量化</td><td>部分，取决于首步是否受权重带宽限制</td><td>步数、是否含 CFG、精度路径</td></tr><tr><td>TPOT</td><td>每步线性层矩阵乘算力</td><td>是，权重变小后每步时延下降</td><td>稀疏度、batch、卡型</td></tr><tr><td>吞吐</td><td>步数 × 批形态 × 每步时延</td><td>是，但被步数稀释</td><td>分辨率、步数、并发上限</td></tr><tr><td>显存</td><td>权重常驻 + 激活峰值 + 掩码</td><td>权重项下降，激活项不变</td><td>batch、CFG、分辨率</td></tr><tr><td>功耗</td><td>整机或单卡能耗</td><td>间接，随算力占用下降</td><td>测量边界、是否含解码</td></tr></tbody></table>\n<p>并发口径同样要写死。在线侧仍按原批调度与 SLO 执行，剪枝不参与在线队列，因此并发上限由调度器与显存决定，不由剪枝决定。把“并发从 N 提到 M”归因于剪枝，只有在显存峰值确实因权重变小而下降、且调度器因此放行更大 batch 时才成立；否则并发提升来自调度策略变更，与剪枝无关。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-47\">四十七 · 数字怎么读：三类不可比的提升</h3>\n<p>第一类不可比是跨步数比较。剪枝模型可以在蒸馏后的少步模型上再次剪枝，此时每请求主干调用次数已经变小，吞吐提升里混入了步数蒸馏的贡献。要拆开，必须固定步数，只对比剪枝前后同一采样器的 TPOT。</p>\n<p>第二类不可比是剪枝与量化混算。剪枝掩码与量化缩放需分别管理，材料未给出叠加后的精度损失数字。若一张表里既有纯剪枝行又有剪枝加 FP8／NVFP4 行，必须分列标注，否则读者会把量化带来的带宽收益误记为剪枝收益。更隐蔽的问题是共用缩放粒度：若量化缩放按剪枝后的稀疏块计算，剪枝误差与量化误差会耦合，精度退化无法归因到单一手段。</p>\n<p>第三类不可比是离线成本被隐去。二阶统计矩阵的存储与求逆在超大 DiT 上带来额外显存与算力开销，层宽越大开销越高。若报表只给在线 TPOT 下降百分比，不给校准样本数、时间步采样策略与求逆耗时，就无法判断这条路径在容量规划上是否值得：校准一次的成本可能抵消多日的在线收益，尤其在请求量低的部署里。</p>\n<div class=\"formula\">$$\\text{净收益} = \\frac{\\Delta \\text{TPOT} \\times N_{\\text{req}} \\times S}{T_{\\text{calib}} + T_{\\text{inv}}} \\quad \\text{需分别报告分子与分母}$$</div>\n<p>这个比值不是要算出一个数，而是提醒报表必须同时给出分子（在线节省的总时延）与分母（离线校准与求逆开销）。只给比值不给分量，读者无法判断在自身请求量下是否划算。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-48\">四十八 · 一个具体例子：同一条请求在两种口径下的读数</h3>\n<p>以一次文生图请求为例：服务端加载已剪枝的 DiT 主干，文本编码器输出提示嵌入，采样器在若干时间步上迭代去噪，每步执行注意力与前馈计算，CFG 把条件与非条件分支拼成一个批。若报表 A 固定步数、固定 batch、固定卡型，只对比剪枝前后 TPOT，得到的下降可以归因于剪枝降低的矩阵乘算力。若报表 B 同时改了步数（换成蒸馏少步模型）又把 CFG 拼批关掉，吞吐提升里就混入了步数减少与批形态变化两项，无法归因。</p>\n<p>再看显存：剪枝降低权重常驻，但激活峰值不变，CFG 拼批仍让峰值翻倍。若报表只报“显存下降”，读者会误以为可以放大 batch；实际能否放大取决于激活峰值与调度器策略，而不是权重项。功耗同理，若测量边界包含 VAE 解码，解码功耗不随剪枝变化，会把剪枝的功耗收益稀释。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-49\">四十九 · 工程判断：先建口径，再谈收益</h3>\n<p>对 OBS-Diff 这类材料未给定量的方法，基准工作的正确顺序是：先在目标 Blackwell 档位上固定模型、步数、batch、CFG 形态与精度路径，建立一张只含剪枝前后 TPOT 与权重显存的对照表；再单独验证剪枝加 FP8／NVFP4 的精度损失；最后把校准样本数、时间步覆盖范围与求逆开销作为离线成本单列。时间步覆盖不足是主要失败模式，覆盖不足时二阶统计无法代表整条采样轨迹，剪枝后在高噪或低噪段出现质量退化，这种退化在只报平均吞吐的报表里完全看不见，必须配合分段质量检查。</p>\n<p>判断一条剪枝收益是否可信，看三件事：报表是否自报硬件档位与并行切分；是否把离线校准成本与在线收益分栏；是否把剪枝与量化的贡献分列。三项缺一，数字就只能当作方向性参考，不能进入容量规划。剪枝掩码与量化缩放分别管理这一条，在工程上意味着加载路径要同时处理稀疏索引与块缩放，任何把两者合并成单一缩放粒度的简化都会放大剪枝误差，这一点在缺少叠加精度数据时只能靠分列实测来兜底。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-50\">五十 · 剪枝收益的边界：口径、失效条件与离线代价</h3>\n<p>读 OBS-Diff 的任何部署收益，先要把口径拆成两段：离线校准与在线推理。离线侧的成本是二阶统计矩阵的存储与求逆，层宽 <span class=\"inline-math\">d</span> 对应 <span class=\"inline-math\">d×d</span> 的 <span class=\"inline-math\">H</span>，单层显存约 <span class=\"inline-math\">4d²</span> 字节（FP32），逐层串行可把峰值压在单层量级，但层宽越大、求逆的算力与数值稳定性代价越高；这部分不进在线队列，却决定了压缩流程能否在单卡或少量卡上完成。在线侧只受益于权重变小后的每步矩阵乘时延下降，扩散主干无 KV cache，显存节省来自权重与激活，因此 TTFT/TPOT 的改善必须归因到 DiT 每步前向，而非缓存命中。</p>\n<div class=\"formula\">$$\\text{在线收益} \\approx \\frac{T_{\\text{step}}(W) - T_{\\text{step}}(\\hat{W})}{T_{\\text{step}}(W)},\\quad \\text{约束：}\\ \\text{Quality}(\\hat{W}) \\ge \\text{SLO}$$</div>\n<p>失效条件集中在时间步覆盖。校准只在若干时间步上累计 <span class=\"inline-math\">H</span>，若采样轨迹的高噪段或低噪段缺席，逐列补偿 <span class=\"inline-math\">δ_q = -w_q/[H^{-1}]_{qq}·H^{-1}_{:,q}</span> 会低估该段的输出误差，剪枝后在这些段出现可见退化；这与稀疏度上限共同构成质量边界，且材料未给出退化程度的可核验数字。与 FP8／NVFP4 叠加时，剪枝掩码与量化缩放需分别管理，若共用缩放粒度会放大剪枝误差，必须分开验证精度。</p>\n<table class=\"mini\"><thead><tr><th>口径</th><th>归属</th><th>可比性判断</th></tr></thead><tbody><tr><td>校准/求逆开销</td><td>离线一次性</td><td>不与在线吞吐同表比较</td></tr><tr><td>权重显存下降</td><td>在线常驻</td><td>需注明稀疏度与量化叠加</td></tr><tr><td>每步时延下降</td><td>在线</td><td>需固定 batch、CFG 批形态与硬件档位</td></tr><tr><td>生成质量漂移</td><td>在线</td><td>需注明时间步覆盖与校准集</td></tr></tbody></table>\n<p>具体例子：同一剪枝模型在 batch 与 CFG 批合并形态不变时，吞吐提升只来自每步矩阵乘变短；若把离线校准耗时计入端到端对比，或把不同硬件档位、不同稀疏度的数字并列，提升即不可比。工程判断是：把 OBS-Diff 当作服务化前置压缩步骤，先在目标档位与 SLO 下测每步时延与质量漂移，再决定稀疏度与是否叠加量化。</p>\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-51\">五十一 · 迁移到非 DiT 主干：先看层结构与激活统计是否成立</h3>\n<p>OBS-Diff 的成立前提只有两条：待剪层是线性层或卷积层，且该层输入激活在采样轨迹上可被校准集覆盖。迁到别的模型时，先按这两条做准入判断，而不是先问“能不能剪”。UNet 类扩散主干（如早期文生图、部分视频扩散）的卷积层占比较高，OBS 的逐列补偿需要在卷积核上做展平重排，把输出通道视为“列”，输入感受野视为特征维；此时二阶统计矩阵的维度是输入通道数乘核面积，层宽不大但核面积会放大矩阵规模，求逆开销上升。迁到 DiT 之外的架构，比如以 Mamba 或线性注意力为主干、或把主干换成 AR 语言模型做多模态生成的形态，逐层误差补偿的假设就被破坏：状态空间层的“权重”与激活之间不是简单的线性映射，OBS 的闭式补偿解不再对应层输出的最小二乘误差，硬套会得到无意义的掩码。</p>\n<p>判断标准可以写成一句可执行的检查：对每个候选层，计算校准激活协方差矩阵的条件数。条件数过高说明激活在特征维上近似共线，$H^{-1}$ 数值不稳定，逐列补偿的 $\\delta_q$ 会被放大，剪枝后层输出误差反而超过直接置零。工程上应把这类层排除在剪枝范围之外，或改用分块对角近似降低求逆规模。代价侧要算清楚：一次校准前向的显存峰值由“最大层宽² × 批大小 × 时间步数”主导，在超大 DiT 上这是离线阶段的主要瓶颈，而不是在线推理的瓶颈；在线只承受权重变小后的矩阵乘时延下降。</p>\n<div class=\"formula\">$$\\kappa(H)=\\frac{\\lambda_{\\max}(H)}{\\lambda_{\\min}(H)},\\quad \\text{准入条件：}\\ \\kappa(H)\\ \\text{有界且}\\ \\lambda_{\\min}(H)\\ \\text{不接近零}$$</div>\n<p>具体例子：把一个以卷积为主的 UNet 主干按 DiT 的逐列流程直接剪，卷积核被展平后列间相关性远高于线性层，$H^{-1}$ 的非对角项主导补偿方向，剪枝后在中低噪段时间步出现结构性纹理崩坏；而把同一流程改为按输出通道分块、块内求逆，退化被限制在局部。这说明迁移的第一改动点是“分块粒度”，不是剪枝率。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-52\">五十二 · 时间步覆盖：迁移到少步采样器与流匹配时的重采样策略</h3>\n<p>前文已讨论过时间步敏感是主要失败模式，这里只讲迁移时的具体改法。OBS-Diff 的校准统计是在离散时间步上累加的，迁到少步蒸馏模型或一致性模型时，采样轨迹从数十步压到几步，时间步集合本身变稀疏，若仍按“均匀采样若干步”收集激活，统计会集中在少数几个噪声水平上，覆盖不到轨迹中段的剧烈分布变化。改法是按采样器的实际调度表取点：对每一步的 $t_i$ 与其相邻区间做加权，权重取该步对最终输出的敏感度近似（可用该步输出对输入的雅可比范数或该步残差幅值做代理），把校准预算按权重分配，而不是均分。</p>\n<p>迁到流匹配采样器时还有一层差异：流匹配的输入是 $(x_t, t)$ 连续时间条件，激活分布随时间连续漂移，离散时间步采样会引入系统性偏差。工程判断是：校准时间步数不能低于采样步数的两倍，且在轨迹两端各留至少一个点，否则高噪段的粗结构误差与低噪段的细节误差会同时被低估。代价上，校准前向次数与时间步数线性相关，时间步翻倍意味着离线校准的算力与显存峰值翻倍，这是迁移到少步模型时容易被忽略的账：少步模型在线便宜，但校准并不因为步数少而变便宜，反而需要更密的取点。</p>\n<p>具体例子：把一个 4 步蒸馏模型按原 50 步模型的均匀取点方案校准，取点落在轨迹的四个离散位置上，中段两个噪声水平之间的激活统计缺失，剪枝后生成结果的构图正确但局部细节出现块状伪影；改为按调度表逐步取点并在步间插值后，伪影消失。这里的改动只是校准侧，采样器与 VAE 路径不变。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-53\">五十三 · 与量化叠加：掩码与缩放粒度必须分开管理</h3>\n<p>迁到已量化的部署栈时，最容易出错的是把剪枝掩码和量化缩放绑在同一套粒度上。OBS-Diff 的补偿权重是在浮点域求出的，若先量化再剪枝，量化误差会污染二阶统计；若先剪枝再量化，稀疏权重在按块缩放时块内非零元素分布不均，缩放因子被少数大值主导，小值被压到量化下限以下。正确顺序是：浮点域完成校准与逐层重建，写回稀疏权重，再按量化方案独立选择缩放粒度，且缩放块边界不应与剪枝分块边界强制对齐——对齐会让一个缩放块内的非零比例过低，等效位宽浪费。</p>\n<p>迁到 NVFP4 这类带块缩放与二级缩放的格式时，还要注意稀疏掩码对反量化路径的影响：稀疏矩阵乘若走结构化稀疏硬件路径，掩码必须满足硬件要求的固定稀疏模式（如每四个元素中固定位置非零），而 OBS 逐列选择产生的是非结构化掩码，两者不兼容。工程判断是：若目标硬件只支持结构化稀疏，OBS-Diff 的收益会被掩码重排吃掉一部分，此时应把剪枝粒度改为按结构化组选择，牺牲部分补偿精度换硬件路径。代价侧，非结构化稀疏在通用矩阵乘上只降低权重显存、不降低算力，只有结构化稀疏才同时降算力；迁移前必须确认目标栈走哪条路径。</p>\n<p>具体例子：在 FP8 栈上先剪枝后量化，若缩放块与剪枝块同边界，块内非零元素少，缩放因子精度被浪费，叠加后的精度损失大于单独剪枝或单独量化；把缩放块改为跨剪枝块滑动后，损失回落。材料未给出叠加后的精度损失数字，因此这条判断只能靠部署侧逐层比对输出误差来验证，不能靠论文结论外推。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-54\">五十四 · 规模上限：二阶统计的存储与求逆决定能剪多大</h3>\n<p>迁移到更大参数量、更宽层的模型时，上限不在剪枝率而在离线成本。逐层 OBS 需要对每个待剪层持有 $H$ 与其逆，$H$ 的维度是输入特征维，存储为 $O(d^2)$，求逆为 $O(d^3)$。当层宽从数千升到上万，单层求逆的算力与显存按立方与平方增长，校准阶段从“单卡可完成”变成“必须分块或分布式”。可行的改法有三条：按输入特征维分块做块对角近似，牺牲跨块相关性换可算性；用低秩近似替代完整求逆，只保留主特征方向；对超宽层直接跳过剪枝，把预算留给窄层。三条改法都降低补偿精度，需要按层输出误差排序决定取舍。</p>\n<p>规模上限还受校准样本数约束：二阶统计的估计误差随样本数下降，宽层需要更多样本才能让 $H$ 可逆且稳定，样本数与层宽同时上升时离线成本是乘性增长。工程判断是：把“可剪层集合”按 $d^2$ 排序，从窄层开始剪，宽层只做量化不做剪枝，这样在超大模型上仍能拿到权重显存收益而不至于让校准不可行。在线侧收益随剪枝覆盖的参数量比例线性变化，覆盖不足时吞吐提升有限，这是规模上限的直接体现。</p>\n<p>具体例子：在一个层宽达到上万的前馈层上强行做完整求逆，校准阶段的显存峰值超过单卡容量，流程无法完成；改为块对角近似后流程可跑，但该层剪枝后的输出误差明显高于窄层，最终部署选择对该层只量化不剪枝。这说明规模上限不是模型参数量，而是“最宽待剪层的 $d^3$ 求逆能否在给定离线预算内完成”。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-55\">五十五 · 领域迁移：哪些推理形态不适用，判断依据是什么</h3>\n<p>迁到视频扩散时，时间维被引入主干，激活统计需要在帧维上累加，校准样本从单张图变成短片段，统计矩阵的估计方差上升；同时视频主干的注意力层常带时序混合，层输入不再是纯线性映射的输入，OBS 的逐层假设在时序注意力上需要重新推导补偿式。判断是：视频扩散可以剪前馈与空间注意力，时序混合层应排除或单独处理。迁到需要强数值保真的领域，比如科学成像重建、医学图像生成，剪枝引入的层输出误差会通过多次采样迭代累积，且这类任务对低频结构的保真要求高于感知质量，OBS 的最小二乘准则优化的是层输出范数误差而非任务指标，两者不一致时剪枝收益为负。</p>\n<p>迁到在线低延迟、单请求小批的形态时，剪枝的收益被批大小稀释：权重变小主要降低每步矩阵乘的显存带宽压力，小批下矩阵乘本就受限于延迟而非带宽，收益有限；这类形态更适合量化而非剪枝。反过来，大批高吞吐形态下权重带宽是瓶颈，剪枝与量化叠加收益最明显。判断依据可以落到一条：看每步矩阵乘是带宽受限还是延迟受限，带宽受限才优先剪枝。</p>\n<p>具体例子：把一个面向高吞吐文生图服务的剪枝方案直接搬到单请求交互式编辑场景，批大小为一时每步时延下降不明显，而校准成本已经付出；同一方案在大批离线渲染队列中则体现出权重显存下降带来的批大小上限提升。这说明迁移的边界由负载形态决定，不由模型架构单独决定。</p>\n\n<h3 id=\"paper-obs-diff-accurate-pruning-for-diffus-2025-sec-56\">五十六 · 工程判断：迁移前必须回答的三个问题</h3>\n<p>第一，目标主干的待剪层是否满足线性映射假设且激活协方差可稳定求逆；不满足的层应排除，排除比例决定收益上限。第二，目标采样器的时间步调度是否允许校准覆盖整条轨迹；少步与连续时间采样器需要更密的取点与敏感度加权，校准预算要按此重算。第三，目标部署栈的稀疏路径是结构化还是非结构化、量化缩放粒度是否与剪枝粒度解耦；两者冲突时优先保硬件路径，牺牲补偿精度。三个问题都指向同一件事：OBS-Diff 是可迁移的离线压缩步骤，但迁移成本落在校准侧，在线收益只在权重带宽受限的形态下兑现。部署侧应把剪枝覆盖的参数量比例、校准显存峰值、叠加量化后的逐层输出误差作为三个准入指标，任一不达标就不进入该模型。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">OBS-Diff: Accurate Pruning</text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\"> For Diffusio…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · OBS-Diff: Accurate Prun… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>材料未给出具体基线方法名称</td></tr><tr><td>主要结果</td><td>材料未给出可核验的定量结果，包括稀疏度、FID 或吞吐数字；论文卡仅能确认…</td></tr><tr><td>消融</td><td>材料未给出消融实验细节，包括校准样本数、时间步采样策略与逐层 versus…</td></tr><tr><td>局限</td><td>材料未给出实验规模、硬件档位与失败模式统计；一次性剪枝对时间步覆盖不足时的…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-obs-diff-accurate-pruning-for-diffus-2025 · 共 9 个片段</p>\n";break;}}})();
